declare j public.file_generation_jobs; v_balance bigint; v_inserted bigint;
begin
  if p_uid is null or length(p_uid) not between 1 and 128 then raise exception '[literal]'; end if;
  perform pg_advisory_xact_lock(hashtextextended('[literal]' || p_uid, 0));
  insert into public.file_generation_accounts(uid) values(p_uid) on conflict do nothing;
  for j in select * from public.file_generation_jobs where uid = p_uid and status = '[literal]' and lease_expires_at <= clock_timestamp() for update loop
    select credits into v_balance from public.file_generation_accounts where uid = p_uid for update;
    v_inserted := null;
    insert into public.file_generation_ledger(uid, job_id, kind, credits_delta, balance_after)
      values(p_uid, j.id, '[literal]', 1, v_balance + 1) on conflict (job_id, kind) do nothing returning id into v_inserted;
    if v_inserted is not null then
      update public.file_generation_accounts set credits = credits + 1, updated_at = now() where uid = p_uid;
    end if;
    update public.file_generation_jobs set status = '[literal]', error_code = '[literal]', updated_at = now() where id = j.id;
  end loop;
end

DECLARE
  a public.activities%ROWTYPE;
BEGIN
  SELECT * INTO a FROM public.activities WHERE id = NEW.activity_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF a.status <> '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF a.seats > 0 AND (SELECT count(*) FROM public.activity_signups s WHERE s.activity_id = NEW.activity_id) >= a.seats THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  RETURN NEW;
END;

BEGIN
  RETURN public.admin_add_member_impl(account, display_name, note);
END;

DECLARE
  v_uid text;
  v_is_super boolean;
  v_existing_role text;
BEGIN
  IF NOT public.is_super_admin_user() THEN RAISE EXCEPTION '[literal]'; END IF;
  PERFORM set_config('[literal]', '[literal]', true);
  v_uid := public.admin_resolve_uid(p_account);
  SELECT is_super_admin INTO v_is_super FROM public.profiles WHERE uid = v_uid;
  IF v_is_super THEN RAISE EXCEPTION '[literal]'; END IF;
  SELECT role INTO v_existing_role FROM public.admin_accounts WHERE account = p_account;
  IF v_existing_role = '[literal]' THEN RAISE EXCEPTION '[literal]'; END IF;
  INSERT INTO public.admin_accounts (account, display_name, role, perms, note)
  VALUES (p_account, p_display, '[literal]',
          jsonb_build_array('[literal]','[literal]','[literal]','[literal]'), p_note)
  ON CONFLICT (account) DO UPDATE SET display_name = EXCLUDED.display_name, note = EXCLUDED.note, updated_at = now();
  UPDATE public.profiles SET is_admin = true, is_super_admin = false, updated_at = now() WHERE uid = v_uid;
  RETURN jsonb_build_object('[literal]', true, '[literal]', v_uid, '[literal]', p_account, '[literal]', '[literal]');
END;

DECLARE v_uid text; v_admin boolean;
BEGIN
  IF NOT public.is_super_admin_user() THEN RAISE EXCEPTION '[literal]'; END IF;
  PERFORM set_config('[literal]', '[literal]', true);
  v_uid := public.admin_resolve_uid(account);
  SELECT (is_admin OR is_super_admin) INTO v_admin FROM public.profiles WHERE uid = v_uid;
  IF v_admin THEN RAISE EXCEPTION '[literal]'; END IF;
  UPDATE public.profiles SET banned_at = now(), banned_note = COALESCE(NULLIF(reason,'[literal]'), '[literal]'), updated_at = now()
  WHERE uid = v_uid AND banned_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION '[literal]'; END IF;
  UPDATE public.secondhand_items SET status = '[literal]', updated_at = now() WHERE creator_uid = v_uid AND status IN ('[literal]','[literal]');
  UPDATE public.tasks SET status = '[literal]', updated_at = now() WHERE creator_uid = v_uid AND status IN ('[literal]','[literal]');
  UPDATE public.activities SET status = '[literal]', updated_at = now() WHERE creator_uid = v_uid AND status = '[literal]';
  UPDATE public.lost_items SET status = '[literal]', updated_at = now() WHERE creator_uid = v_uid AND status = '[literal]';
  DELETE FROM public.activity_signups WHERE uid = v_uid;
  UPDATE public.partner_apps SET status = '[literal]', handled_at = now() WHERE creator_uid = v_uid AND status = '[literal]';
  UPDATE public.canteen_apply_apps SET status = '[literal]' WHERE creator_uid = v_uid AND status = '[literal]';
  UPDATE public.canteen_orders SET status = '[literal]', updated_at = now() WHERE buyer_uid = v_uid AND status = '[literal]';
  RETURN jsonb_build_object('[literal]', true, '[literal]', v_uid, '[literal]', account, '[literal]', true, '[literal]', COALESCE(NULLIF(reason,'[literal]'), '[literal]'));
END;

DECLARE v_id bigint; v_out jsonb := '[literal]'::jsonb; v_count integer;
BEGIN
  IF auth.uid() IS NULL OR public.current_is_anon() OR NOT coalesce(public.is_admin_user(), false) THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF p_confirmation IS DISTINCT FROM '[literal]' THEN RAISE EXCEPTION '[literal]'; END IF;
  v_count := coalesce(cardinality(p_shop_ids), 0) + coalesce(cardinality(p_stall_ids), 0);
  IF v_count < 1 OR v_count > 300 THEN RAISE EXCEPTION '[literal]'; END IF;
  IF EXISTS (SELECT 1 FROM unnest(coalesce(p_shop_ids, '[literal]'::bigint[])) AS selected(id) WHERE id IS NULL OR id <= 0)
     OR EXISTS (SELECT 1 FROM unnest(coalesce(p_stall_ids, '[literal]'::bigint[])) AS selected(id) WHERE id IS NULL OR id <= 0) THEN RAISE EXCEPTION '[literal]'; END IF;
  IF (SELECT count(DISTINCT id) FROM unnest(coalesce(p_shop_ids, '[literal]'::bigint[])) AS selected(id)) <> coalesce(cardinality(p_shop_ids), 0)
     OR (SELECT count(DISTINCT id) FROM unnest(coalesce(p_stall_ids, '[literal]'::bigint[])) AS selected(id)) <> coalesce(cardinality(p_stall_ids), 0) THEN RAISE EXCEPTION '[literal]'; END IF;
  IF EXISTS (SELECT 1 FROM unnest(coalesce(p_shop_ids, '[literal]'::bigint[])) AS selected(id) WHERE NOT EXISTS (SELECT 1 FROM public.shop_stores s WHERE s.id = selected.id))
     OR EXISTS (SELECT 1 FROM unnest(coalesce(p_stall_ids, '[literal]'::bigint[])) AS selected(id) WHERE NOT EXISTS (SELECT 1 FROM public.canteen_stores s WHERE s.id = selected.id)) THEN RAISE EXCEPTION '[literal]'; END IF;
  FOR v_id IN SELECT id FROM unnest(coalesce(p_shop_ids, '[literal]'::bigint[])) AS selected(id) ORDER BY id LOOP
    v_out := v_out || jsonb_build_array(public.admin_operation_revoke('[literal]', v_id, p_reason, true));
  END LOOP;
  FOR v_id IN SELECT id FROM unnest(coalesce(p_stall_ids, '[literal]'::bigint[])) AS selected(id) ORDER BY id LOOP
    v_out := v_out || jsonb_build_array(public.admin_operation_revoke('[literal]', v_id, p_reason, true));
  END LOOP;
  RETURN jsonb_build_object('[literal]', v_count, '[literal]', v_out);
END;

DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR public.current_is_anon() OR NOT coalesce(public.is_admin_user(), false) THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF p_kind = '[literal]' THEN
    SELECT coalesce(jsonb_agg(to_jsonb(row_data) ORDER BY row_data.id), '[literal]'::jsonb) INTO v_result FROM (
      SELECT s.id, '[literal]'::text AS kind, s.name, s.owner_uid, s.status,
        s.operation_revoked AS revoked, s.operation_cleared AS cleared, s.operation_reason AS reason,
        (SELECT count(*) FROM public.shop_orders o WHERE o.store_id = s.id AND o.status IN ('[literal]', '[literal]', '[literal]')) AS pending_orders,
        (SELECT count(*) FROM public.shop_goods g WHERE g.store_id = s.id AND g.status = '[literal]') AS listed_items,
        (SELECT count(*) FROM public.shop_groups g WHERE g.store_id = s.id AND g.status = '[literal]') AS open_groups
      FROM public.shop_stores s
    ) row_data;
  ELSIF p_kind = '[literal]' THEN
    SELECT coalesce(jsonb_agg(to_jsonb(row_data) ORDER BY row_data.id), '[literal]'::jsonb) INTO v_result FROM (
      SELECT s.id, '[literal]'::text AS kind, s.name, s.owner_uid, s.status, s.operation_revoked AS revoked,
        s.operation_cleared AS cleared, s.operation_reason AS reason,
        (SELECT count(*) FROM public.canteen_orders o WHERE o.store_id = s.id AND o.status IN ('[literal]', '[literal]', '[literal]')) AS pending_orders,
        (SELECT count(*) FROM public.canteen_dishes d WHERE d.store_id = s.id AND d.status = '[literal]') AS listed_items,
        0::bigint AS open_groups
      FROM public.canteen_stores s
    ) row_data;
  ELSE RAISE EXCEPTION '[literal]'; END IF;
  RETURN v_result;
END;

DECLARE
  v_snapshot jsonb; v_owner text; v_unlisted bigint := 0; v_groups bigint := 0; v_pending bigint := 0;
  v_cleared boolean; v_previous_setting text := coalesce(current_setting('[literal]', true), '[literal]');
BEGIN
  IF auth.uid() IS NULL OR public.current_is_anon() OR NOT coalesce(public.is_admin_user(), false) THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF p_kind NOT IN ('[literal]', '[literal]') OR p_kind IS NULL OR coalesce(p_store_id, 0) <= 0 THEN RAISE EXCEPTION '[literal]'; END IF;
  IF length(btrim(coalesce(p_reason, '[literal]'))) < 2 OR length(btrim(p_reason)) > 60 THEN RAISE EXCEPTION '[literal]'; END IF;
  PERFORM pg_advisory_xact_lock(612004, 1);
  IF p_kind = '[literal]' THEN
    SELECT to_jsonb(s), s.owner_uid INTO v_snapshot, v_owner FROM public.shop_stores s WHERE s.id = p_store_id FOR UPDATE;
  ELSE
    SELECT to_jsonb(s), s.owner_uid INTO v_snapshot, v_owner FROM public.canteen_stores s WHERE s.id = p_store_id FOR UPDATE;
  END IF;
  IF v_snapshot IS NULL THEN RAISE EXCEPTION '[literal]'; END IF;
  v_cleared := coalesce(p_clear, false) OR coalesce((v_snapshot->>'[literal]')::boolean, false);
  PERFORM set_config('[literal]', '[literal]', true);
  IF p_kind = '[literal]' THEN
    UPDATE public.shop_stores SET status = '[literal]', force_closed = true, force_close_note = btrim(p_reason), force_closed_at = now(),
      operation_revoked = true, operation_cleared = v_cleared, operation_reason = btrim(p_reason), operation_revoked_by = auth.uid(), operation_revoked_at = now(), updated_at = now()
      WHERE id = p_store_id;
    SELECT count(*) INTO v_groups FROM public.shop_groups WHERE store_id = p_store_id AND status = '[literal]';
    UPDATE public.shop_group_members m SET status = '[literal]'
      WHERE m.status = '[literal]' AND EXISTS (SELECT 1 FROM public.shop_groups g WHERE g.id = m.group_id AND g.store_id = p_store_id AND g.status = '[literal]');
    UPDATE public.shop_groups SET status = '[literal]', settled_at = now() WHERE store_id = p_store_id AND status = '[literal]';
    UPDATE public.shop_goods SET status = '[literal]', updated_at = now() WHERE store_id = p_store_id AND status <> '[literal]';
    GET DIAGNOSTICS v_unlisted = ROW_COUNT;
    SELECT count(*) INTO v_pending FROM public.shop_orders WHERE store_id = p_store_id AND status IN ('[literal]', '[literal]', '[literal]');
    UPDATE public.role_members SET status = '[literal]', updated_at = now() WHERE uid = v_owner AND role = '[literal]' AND status = '[literal]'
      AND NOT EXISTS (SELECT 1 FROM public.shop_stores s WHERE s.owner_uid = v_owner AND NOT s.operation_revoked AND s.status <> '[literal]');
    UPDATE public.shop_products SET status = '[literal]', updated_at = now() WHERE owner_uid = v_owner AND status <> '[literal]'
      AND NOT EXISTS (SELECT 1 FROM public.shop_stores s WHERE s.owner_uid = v_owner AND NOT s.operation_revoked AND s.status <> '[literal]');
  ELSE
    UPDATE public.canteen_stores SET status = '[literal]', force_closed = true, force_close_note = btrim(p_reason), force_closed_at = now(),
      operation_revoked = true, operation_cleared = v_cleared, operation_reason = btrim(p_reason), operation_revoked_by = auth.uid(), operation_revoked_at = now(), updated_at = now()
      WHERE id = p_store_id;
    UPDATE public.canteen_dishes SET status = '[literal]', updated_at = now() WHERE store_id = p_store_id AND status <> '[literal]';
    GET DIAGNOSTICS v_unlisted = ROW_COUNT;
    SELECT count(*) INTO v_pending FROM public.canteen_orders WHERE store_id = p_store_id AND status IN ('[literal]', '[literal]', '[literal]');
    UPDATE public.role_members SET status = '[literal]', updated_at = now() WHERE uid = v_owner AND role = '[literal]' AND status = '[literal]'
      AND NOT EXISTS (SELECT 1 FROM public.canteen_stores s WHERE s.owner_uid = v_owner AND NOT s.operation_revoked);
  END IF;
  INSERT INTO public.operation_governance_log(kind, store_id, owner_uid, actor_uid, reason, cleared, store_before, unlisted_items, closed_groups)
    VALUES (p_kind, p_store_id, v_owner, auth.uid(), btrim(p_reason), v_cleared, v_snapshot, v_unlisted, v_groups);
  PERFORM set_config('[literal]', v_previous_setting, true);
  RETURN jsonb_build_object('[literal]', p_kind, '[literal]', p_store_id, '[literal]', true, '[literal]', v_cleared,
    '[literal]', v_unlisted, '[literal]', v_pending, '[literal]', v_groups);
END;

DECLARE v_uid text; v_deleted int; v_me text := auth.uid();
BEGIN
  IF NOT public.is_super_admin_user() THEN RAISE EXCEPTION '[literal]'; END IF;
  PERFORM set_config('[literal]', '[literal]', true);
  v_uid := public.admin_resolve_uid(account);
  IF v_uid = v_me THEN RAISE EXCEPTION '[literal]'; END IF;
  DELETE FROM public.admin_accounts a USING auth.users u
  WHERE a.role = '[literal]'
    AND (u.phone_number = a.account OR u.phone_number = '[literal]' || a.account OR u.username = a.account)
    AND u.id::text = v_uid;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  IF v_deleted = 0 THEN RAISE EXCEPTION '[literal]'; END IF;
  UPDATE public.profiles SET is_admin = false, is_super_admin = false, updated_at = now() WHERE uid = v_uid;
  RETURN jsonb_build_object('[literal]', true, '[literal]', v_uid, '[literal]', account, '[literal]', true);
END;

DECLARE v_uid text;
BEGIN
  IF NOT public.is_super_admin_user() THEN RAISE EXCEPTION '[literal]'; END IF;
  SELECT u.id::text INTO v_uid FROM auth.users u
  WHERE u.phone_number = account OR u.phone_number = '[literal]' || account OR u.username = account
  ORDER BY (u.phone_number = account OR u.phone_number = '[literal]' || account) DESC, (u.username = account) DESC
  LIMIT 1;
  IF v_uid IS NULL THEN RAISE EXCEPTION '[literal]'; END IF;
  RETURN v_uid;
END;

DECLARE
  v_uid text;
  v_actor text := auth.uid();
  v_blocked boolean;
  v_protected boolean;
  v_result jsonb;
  v_reason text := left(coalesce(nullif(btrim(reason), '[literal]'), '[literal]'), 120);
BEGIN
  IF v_actor IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.uid = v_actor AND p.is_super_admin AND p.banned_at IS NULL
  ) THEN
    RAISE EXCEPTION '[literal]' USING ERRCODE = '[literal]';
  END IF;
  IF banned IS NULL OR nullif(btrim(account), '[literal]') IS NULL OR nullif(btrim(target_uid), '[literal]') IS NULL THEN
    RAISE EXCEPTION '[literal]' USING ERRCODE = '[literal]';
  END IF;
  v_uid := public.admin_resolve_uid(account);
  IF v_uid IS DISTINCT FROM target_uid THEN
    RAISE EXCEPTION '[literal]' USING ERRCODE = '[literal]';
  END IF;
  SELECT p.banned_at IS NOT NULL, coalesce(p.is_admin, false) OR coalesce(p.is_super_admin, false)
    INTO v_blocked, v_protected FROM public.profiles p WHERE p.uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '[literal]'; END IF;
  IF v_protected THEN RAISE EXCEPTION '[literal]' USING ERRCODE = '[literal]'; END IF;

  IF banned THEN
    IF NOT v_blocked THEN
      v_result := public.admin_ban_user(account, v_reason);
      IF v_result->>'[literal]' IS DISTINCT FROM v_uid THEN RAISE EXCEPTION '[literal]'; END IF;
    END IF;
    INSERT INTO public.user_sanctions(uid, kind, until_at, reason, actor_uid, created_at)
      SELECT v_uid, '[literal]', NULL, v_reason, v_actor, now()
      WHERE NOT EXISTS (
        SELECT 1 FROM public.user_sanctions s WHERE s.uid = v_uid AND s.kind = '[literal]' AND s.until_at IS NULL
      );
  ELSE
    IF v_blocked THEN
      v_result := public.admin_unban_user(account);
      IF v_result->>'[literal]' IS DISTINCT FROM v_uid THEN RAISE EXCEPTION '[literal]'; END IF;
    END IF;
    DELETE FROM public.user_sanctions s WHERE s.uid = v_uid AND s.kind = '[literal]';
  END IF;
  RETURN jsonb_build_object('[literal]', true, '[literal]', v_uid, '[literal]', account, '[literal]', banned);
END;

BEGIN
  IF NEW.role = '[literal]' THEN
    NEW.display_name := '[literal]';
    NEW.note := '[literal]';
  END IF;
  RETURN NEW;
END;

DECLARE v_uid text;
BEGIN
  IF NOT public.is_super_admin_user() THEN RAISE EXCEPTION '[literal]'; END IF;
  PERFORM set_config('[literal]', '[literal]', true);
  v_uid := public.admin_resolve_uid(account);
  UPDATE public.profiles SET banned_at = NULL, banned_note = NULL, updated_at = now()
  WHERE uid = v_uid AND banned_at IS NOT NULL;
  IF NOT FOUND THEN RAISE EXCEPTION '[literal]'; END IF;
  RETURN jsonb_build_object('[literal]', true, '[literal]', v_uid, '[literal]', account, '[literal]', true);
END;

begin
  if new.status='[literal]' and old.status='[literal]' then
    if not public.is_admin_user() then raise exception '[literal]'; end if;
    insert into public.campus_pois(campus_id,name,category,lng,lat,enabled,verification_status,verified_at,image_urls,note)
    values (new.campus_id,new.name,new.category,new.lng,new.lat,true,'[literal]',now(),new.image_urls,new.note)
    on conflict (campus_id,name) do nothing;
    if not found then
      raise exception '[literal]';
    end if;
    new.reviewed_at=now();
  elsif new.status='[literal]' and old.status='[literal]' then
    if not public.is_admin_user() then raise exception '[literal]'; end if;
    new.reviewed_at=now();
  end if;
  return new;
end;

begin
  if tg_op = '[literal]' then
    update public.campus_posts set like_count = like_count + 1 where id = new.post_id;
    return new;
  end if;
  update public.campus_posts set like_count = greatest(0, like_count - 1) where id = old.post_id;
  return old;
end;

