DECLARE
  v_row public.canteen_apply_apps%ROWTYPE;
  v_store_id bigint;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  SELECT * INTO v_row FROM public.canteen_apply_apps WHERE id = apply_id AND status = '[literal]';
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  INSERT INTO public.canteen_stores (owner_uid, name, emoji, description, tags, building, status)
  VALUES (v_row.creator_uid, v_row.store_name, v_row.emoji, v_row.description,
          v_row.tags, v_row.building, '[literal]')
  RETURNING id INTO v_store_id;
  UPDATE public.canteen_apply_apps
     SET status = '[literal]', handled_at = now(), updated_at = now()
   WHERE id = apply_id;
  RETURN v_store_id;
END;

DECLARE
  v_rider_uid text := auth.uid();
BEGIN
  -- (a) 配送单出餐完成自动入池
  IF NEW.mode = '[literal]' AND NEW.status = '[literal]'
     AND OLD.status IS DISTINCT FROM NEW.status
     AND NEW.delivery_status IN ('[literal]', '[literal]') THEN
    NEW.delivery_status := '[literal]';
    NEW.rider_uid := '[literal]';
    NEW.rider_name := '[literal]';
    NEW.rider_phone := '[literal]';
    NEW.delivery_note := '[literal]';
    NEW.delivery_taken_at := NULL;
    NEW.delivery_done_at := NULL;
    RETURN NEW;
  END IF;

  -- (b) 订单被取消 / 拒单：在途配送态回收，避免骑手列表残留幽灵单
  --     注意保留 rider_uid：骑手仍需要在自己「已送达 / 已取消」分组里回看这条单
  IF NEW.status IN ('[literal]', '[literal]') AND OLD.status IS DISTINCT FROM NEW.status
     AND OLD.delivery_status NOT IN ('[literal]', '[literal]', '[literal]') THEN
    NEW.delivery_status := '[literal]';
    RETURN NEW;
  END IF;

  -- (b2) 档口把配送单直接标「完成」时，若还停在待接单池（始终无人接单），
  --      配送态收尾为 cancelled，避免「订单已完成却永远占着池位」的脏数据。
  --      已在途（taken/picked/riding/arrived）的单不在此改写：骑手仍在路上，
  --      由他继续推进到「已送达」完成闭环（rider_step_impl 已允许 status='[literal]' 后继续收尾）。
  IF NEW.status = '[literal]' AND OLD.status IS DISTINCT FROM NEW.status
     AND NEW.delivery_status = '[literal]' THEN
    NEW.delivery_status := '[literal]';
    RETURN NEW;
  END IF;

  -- 非配送态变更直接放行
  IF NEW.delivery_status IS NOT DISTINCT FROM OLD.delivery_status
     AND NEW.rider_uid IS NOT DISTINCT FROM OLD.rider_uid THEN
    RETURN NEW;
  END IF;

  -- 自取订单不允许出现配送态
  IF NEW.mode <> '[literal]' AND NEW.delivery_status <> '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- (c) 管理员（平台治理 / 代指派）不受状态机约束
  IF public.is_admin_user() THEN
    RETURN NEW;
  END IF;

  IF NOT public.rider_is_approved() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 回池放行：本人将已在途（未送达）的订单释放回池，骑手归属清空
  IF OLD.rider_uid = v_rider_uid AND NEW.rider_uid = '[literal]' AND NEW.delivery_status = '[literal]'
     AND OLD.delivery_status IN ('[literal]', '[literal]', '[literal]') THEN
    RETURN NEW;
  END IF;

  IF NEW.rider_uid <> v_rider_uid THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 骑手只允许沿状态机前进；回池统一走 rider_cancel_order RPC（会置 rider_uid = '[literal]'）
  IF NOT (
    (OLD.delivery_status = '[literal]' AND NEW.delivery_status = '[literal]')
    OR (OLD.delivery_status = '[literal]' AND NEW.delivery_status = '[literal]')
    OR (OLD.delivery_status = '[literal]' AND NEW.delivery_status = '[literal]')
    OR (OLD.delivery_status = '[literal]' AND NEW.delivery_status = '[literal]')
    OR (OLD.delivery_status = '[literal]' AND NEW.delivery_status = '[literal]')
  ) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  RETURN NEW;
END;

DECLARE
  v_owner      text;
  v_store_name text;
  v_label      text;
BEGIN
  SELECT s.owner_uid, s.name INTO v_owner, v_store_name
    FROM public.canteen_stores s
   WHERE s.id = NEW.store_id;

  IF TG_OP = '[literal]' THEN
    IF coalesce(v_owner, '[literal]') <> '[literal]' THEN
      PERFORM public.notify_push(
        v_owner, '[literal]', '[literal]',
        format('[literal]',
               coalesce(nullif(btrim(NEW.buyer_name), '[literal]'), '[literal]'),
               to_char(NEW.total::numeric, '[literal]')),
        '[literal]', NEW.id
      );
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    v_label := CASE NEW.status
                 WHEN '[literal]' THEN '[literal]'
                 WHEN '[literal]'    THEN '[literal]'
                 WHEN '[literal]'     THEN '[literal]'
                 WHEN '[literal]' THEN '[literal]'
                 WHEN '[literal]' THEN '[literal]'
                 ELSE '[literal]'
               END;

    IF coalesce(NEW.buyer_uid, '[literal]') <> '[literal]' THEN
      PERFORM public.notify_push(
        NEW.buyer_uid, '[literal]', '[literal]',
        format('[literal]', NEW.id, v_label,
               CASE WHEN NEW.status = '[literal]' AND coalesce(btrim(NEW.reject_reason), '[literal]') <> '[literal]'
                    THEN '[literal]' || btrim(NEW.reject_reason) ELSE '[literal]' END),
        '[literal]', NEW.id
      );
    END IF;

    IF NEW.status = '[literal]' AND coalesce(v_owner, '[literal]') <> '[literal]' THEN
      PERFORM public.notify_push(
        v_owner, '[literal]', '[literal]',
        format('[literal]', NEW.id),
        '[literal]', NEW.id
      );
    END IF;
  END IF;

  IF NEW.delivery_status IS DISTINCT FROM OLD.delivery_status
     AND coalesce(NEW.rider_uid, '[literal]') <> '[literal]' THEN
    IF NEW.delivery_status = '[literal]' THEN
      IF coalesce(NEW.buyer_uid, '[literal]') <> '[literal]' THEN
        PERFORM public.notify_push(
          NEW.buyer_uid, '[literal]', '[literal]',
          format('[literal]', NEW.id),
          '[literal]', NEW.id
        );
      END IF;
      IF coalesce(v_owner, '[literal]') <> '[literal]' THEN
        PERFORM public.notify_push(
          v_owner, '[literal]', '[literal]',
          format('[literal]', NEW.id),
          '[literal]', NEW.id
        );
      END IF;
    ELSIF OLD.delivery_status = '[literal]' AND NEW.delivery_status = '[literal]' THEN
      IF coalesce(NEW.buyer_uid, '[literal]') <> '[literal]' THEN
        PERFORM public.notify_push(
          NEW.buyer_uid, '[literal]', '[literal]',
          format('[literal]', NEW.id),
          '[literal]', NEW.id
        );
      END IF;
      PERFORM public.notify_push(
        NEW.rider_uid, '[literal]', '[literal]',
        format('[literal]', NEW.id),
        '[literal]', NEW.id
      );
    END IF;
  END IF;

  RETURN NEW;
END;

BEGIN
  PERFORM public.canteen_settle_impl(NEW.id);
  RETURN NEW;
END;

DECLARE
  v_code text;
  v_try integer;
BEGIN
  -- 非状态列更新（如改 note/拒单原因草稿）直接放行
  IF OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  -- 拒单必须填写原因
  IF NEW.status = '[literal]' AND btrim(COALESCE(NEW.reject_reason, '[literal]')) = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 管理员（平台治理/代运营）不受状态流约束
  IF NOT public.is_admin_user() THEN
    IF auth.uid() = OLD.buyer_uid THEN
      -- 买家侧：仅取消制作中的订单 / 取餐后确认完成
      IF NOT (
        (OLD.status IN ('[literal]', '[literal]') AND NEW.status = '[literal]')
        OR (OLD.status = '[literal]' AND NEW.status = '[literal]')
      ) THEN
        RAISE EXCEPTION '[literal]';
      END IF;
    ELSIF public.canteen_is_store_owner(OLD.store_id) AND auth.uid() <> OLD.buyer_uid THEN
      -- 档口主侧：接单 / 出餐 / 拒单 / 取消（仅未出餐时）
      IF NOT (
        (OLD.status = '[literal]' AND NEW.status IN ('[literal]', '[literal]', '[literal]'))
        OR (OLD.status = '[literal]' AND NEW.status IN ('[literal]', '[literal]', '[literal]'))
        OR (OLD.status = '[literal]' AND NEW.status = '[literal]')
      ) THEN
        RAISE EXCEPTION '[literal]';
      END IF;
    ELSE
      RAISE EXCEPTION '[literal]';
    END IF;
  END IF;

  -- 取餐码：转入 accepted/ready 且未生成时，自动生成同档口在途唯一 4 位数字码
  IF NEW.status IN ('[literal]', '[literal]') AND btrim(COALESCE(NEW.pickup_code, '[literal]')) = '[literal]' THEN
    v_code := lpad((floor(random() * 10000))::int::text, 4, '[literal]');
    v_try := 1;
    WHILE v_try < 10 AND EXISTS (
      SELECT 1 FROM public.canteen_orders o
      WHERE o.store_id = NEW.store_id AND o.id <> NEW.id
        AND o.status IN ('[literal]', '[literal]') AND o.pickup_code = v_code
    ) LOOP
      v_code := lpad((floor(random() * 10000))::int::text, 4, '[literal]');
      v_try := v_try + 1;
    END LOOP;
    NEW.pickup_code := v_code;
  END IF;

  RETURN NEW;
END;

BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF btrim(COALESCE(reason, '[literal]')) = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  UPDATE public.canteen_apply_apps
     SET status = '[literal]', reply = reason, handled_at = now(), updated_at = now()
   WHERE id = apply_id AND status = '[literal]';
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  RETURN true;
END;

BEGIN
  IF public.is_admin_user() THEN
    RETURN NEW;
  END IF;
  IF public.canteen_review_store_owner(NEW.id) THEN
    IF NEW.score <> OLD.score OR NEW.content <> OLD.content OR NEW.rater_name <> OLD.rater_name
       OR NEW.rater_uid <> OLD.rater_uid OR NEW.store_id <> OLD.store_id OR NEW.order_id <> OLD.order_id THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    IF NEW.reply <> OLD.reply THEN
      NEW.replied_at := now();
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION '[literal]';
END;

DECLARE
  v_order      public.canteen_orders%ROWTYPE;
  v_owner_uid  text;
  v_total_cent bigint;
  v_comm_bp    integer;
  v_rider_bp   integer;
  v_fee_cent   bigint;
  v_rider_cent bigint;
  v_store_cent bigint;
  v_bal        bigint;
  v_money      text;
  v_terminal   boolean;
BEGIN
  SELECT * INTO v_order FROM public.canteen_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]', p_order_id;
  END IF;

  IF v_order.settle_status <> '[literal]' THEN
    RETURN jsonb_build_object(
      '[literal]', false, '[literal]', true,
      '[literal]', v_order.total::bigint * 100,
      '[literal]', v_order.platform_fee_cent,
      '[literal]', v_order.store_income_cent,
      '[literal]', v_order.rider_income_cent
    );
  END IF;

  -- 业务终态：自取单看 status，配送单看 delivery_status
  IF v_order.mode = '[literal]' THEN
    v_terminal := (v_order.delivery_status = '[literal]');
  ELSE
    v_terminal := (v_order.status = '[literal]');
  END IF;

  IF NOT v_terminal THEN
    RETURN jsonb_build_object(
      '[literal]', false, '[literal]', true,
      '[literal]', v_order.total::bigint * 100,
      '[literal]', 0, '[literal]', 0, '[literal]', 0
    );
  END IF;

  v_total_cent := v_order.total::bigint * 100;
  v_money := to_char(v_total_cent / 100.0, '[literal]');

  SELECT owner_uid INTO v_owner_uid FROM public.canteen_stores WHERE id = v_order.store_id;

  SELECT r.commission_bp, r.rider_bp
    INTO v_comm_bp, v_rider_bp
    FROM public.commission_rules r
   WHERE r.scope = '[literal]' AND r.ref_id = v_order.store_id AND r.enabled
   LIMIT 1;

  IF v_comm_bp IS NULL THEN
    SELECT r.commission_bp, r.rider_bp
      INTO v_comm_bp, v_rider_bp
      FROM public.commission_rules r
     WHERE r.scope = '[literal]' AND r.ref_id = 0 AND r.enabled
     LIMIT 1;
  END IF;

  IF v_comm_bp IS NULL THEN
    v_comm_bp := 500;
    v_rider_bp := 1000;
  END IF;

  v_fee_cent := round(v_total_cent * v_comm_bp / 10000.0)::bigint;

  IF v_order.mode = '[literal]'
     AND coalesce(v_order.rider_uid, '[literal]') <> '[literal]'
     AND v_order.delivery_status = '[literal]' THEN
    v_rider_cent := round(v_total_cent * v_rider_bp / 10000.0)::bigint;
  ELSE
    v_rider_cent := 0;
  END IF;

  v_store_cent := v_total_cent - v_fee_cent - v_rider_cent;
  IF v_store_cent < 0 THEN
    v_store_cent := 0;
  END IF;

  IF v_fee_cent > 0 THEN
    INSERT INTO public.wallets (uid, account, balance_cent)
    VALUES ('[literal]', '[literal]', v_fee_cent)
    ON CONFLICT (uid, account) DO UPDATE
      SET balance_cent = wallets.balance_cent + EXCLUDED.balance_cent,
          updated_at = now()
    RETURNING balance_cent INTO v_bal;

    INSERT INTO public.wallet_ledger (uid, account, kind, amount_cent, balance_after, order_id, memo)
    VALUES ('[literal]', '[literal]', '[literal]', v_fee_cent, v_bal, p_order_id,
            format('[literal]', p_order_id));
  END IF;

  IF v_store_cent > 0 AND coalesce(v_owner_uid, '[literal]') <> '[literal]' THEN
    INSERT INTO public.wallets (uid, account, balance_cent)
    VALUES (v_owner_uid, '[literal]', v_store_cent)
    ON CONFLICT (uid, account) DO UPDATE
      SET balance_cent = wallets.balance_cent + EXCLUDED.balance_cent,
          updated_at = now()
    RETURNING balance_cent INTO v_bal;

    INSERT INTO public.wallet_ledger (uid, account, kind, amount_cent, balance_after, order_id, memo)
    VALUES (v_owner_uid, '[literal]', '[literal]', v_store_cent, v_bal, p_order_id,
            format('[literal]', p_order_id, v_money));

    PERFORM public.notify_push(
      v_owner_uid, '[literal]', '[literal]',
      format('[literal]', p_order_id, to_char(v_store_cent / 100.0, '[literal]')),
      '[literal]', p_order_id
    );
  END IF;

  IF v_rider_cent > 0 THEN
    INSERT INTO public.wallets (uid, account, balance_cent)
    VALUES (v_order.rider_uid, '[literal]', v_rider_cent)
    ON CONFLICT (uid, account) DO UPDATE
      SET balance_cent = wallets.balance_cent + EXCLUDED.balance_cent,
          updated_at = now()
    RETURNING balance_cent INTO v_bal;

    INSERT INTO public.wallet_ledger (uid, account, kind, amount_cent, balance_after, order_id, memo)
    VALUES (v_order.rider_uid, '[literal]', '[literal]', v_rider_cent, v_bal, p_order_id,
            format('[literal]', p_order_id));

    PERFORM public.notify_push(
      v_order.rider_uid, '[literal]', '[literal]',
      format('[literal]', p_order_id, to_char(v_rider_cent / 100.0, '[literal]')),
      '[literal]', p_order_id
    );
  END IF;

  UPDATE public.canteen_orders
     SET settle_status = '[literal]',
         platform_fee_cent = v_fee_cent,
         store_income_cent = v_store_cent,
         rider_income_cent = v_rider_cent,
         settled_at = now()
   WHERE id = p_order_id;

  RETURN jsonb_build_object(
    '[literal]', true, '[literal]', false,
    '[literal]', v_total_cent,
    '[literal]', v_fee_cent,
    '[literal]', v_store_cent,
    '[literal]', v_rider_cent
  );
END;

BEGIN
  IF (NEW.force_closed IS DISTINCT FROM OLD.force_closed
      OR NEW.force_close_note IS DISTINCT FROM OLD.force_close_note
      OR NEW.force_closed_at IS DISTINCT FROM OLD.force_closed_at)
     AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  RETURN NEW;
END;

DECLARE
  v_uid    text := auth.uid();
  v_wallet public.pet_cat_wallets%ROWTYPE;
  v_items  jsonb;
  v_vouchers jsonb;
  v_transfers jsonb;
  v_step  CONSTANT bigint  := 100000;
  v_award CONSTANT integer := 30000;
  v_total bigint;
  v_next  bigint;
  v_fund  bigint;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_wallet FROM public.pet_cat_wallets WHERE uid = v_uid;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           '[literal]', i.key, '[literal]', i.name, '[literal]', i.icon, '[literal]', i.kind,
           '[literal]', i.points_cost, '[literal]', i.description
         ) ORDER BY i.sort), '[literal]'::jsonb)
    INTO v_items
    FROM public.cat_charity_items i
   WHERE i.enabled;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           '[literal]', e.voucher_code, '[literal]', e.item_key, '[literal]', e.item_name,
           '[literal]', e.points_cost, '[literal]', e.created_at
         ) ORDER BY e.created_at DESC), '[literal]'::jsonb)
    INTO v_vouchers
    FROM (
      SELECT * FROM public.pet_cat_exchanges
       WHERE uid = v_uid
       ORDER BY created_at DESC
       LIMIT 10
    ) e;

  -- 我参与的最近 10 笔转让（两个方向都算，带 from/to 便于前端区分）
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           '[literal]', t.id, '[literal]', CASE WHEN t.from_uid = v_uid THEN '[literal]' ELSE '[literal]' END,
           '[literal]', t.from_name, '[literal]', t.to_name,
           '[literal]', t.points, '[literal]', t.note, '[literal]', t.created_at
         ) ORDER BY t.created_at DESC), '[literal]'::jsonb)
    INTO v_transfers
    FROM (
      SELECT * FROM public.pet_cat_transfers
       WHERE from_uid = v_uid OR to_uid = v_uid
       ORDER BY created_at DESC
       LIMIT 10
    ) t;

  SELECT COALESCE(sum(earned_total), 0) INTO v_total FROM public.pet_cat_wallets;
  v_next := (floor(COALESCE(v_total, 0) / v_step) + 1) * v_step;
  SELECT COALESCE(sum(x.points_cost), 0) + COALESCE((SELECT sum(m.awarded) FROM public.pet_cat_milestones m), 0)
    INTO v_fund
    FROM public.pet_cat_exchanges x
    JOIN public.cat_charity_items i ON i.key = x.item_key
   WHERE i.kind = '[literal]';

  RETURN jsonb_build_object(
    '[literal]', COALESCE(v_wallet.balance, 0),
    '[literal]', COALESCE(v_wallet.earned_total, 0),
    '[literal]', v_items,
    '[literal]', v_vouchers,
    '[literal]', v_transfers,
    '[literal]', jsonb_build_object(
      '[literal]', (SELECT count(*) FROM public.pet_cat_wallets),
      '[literal]', v_total,
      '[literal]', (SELECT count(*) FROM public.pet_cat_exchanges x
                      JOIN public.cat_charity_items i ON i.key = x.item_key
                     WHERE i.kind = '[literal]'),
      '[literal]', v_fund,
      '[literal]', v_step,
      '[literal]', v_next,
      '[literal]', (SELECT COALESCE(sum(m.awarded), 0) FROM public.pet_cat_milestones m)
    ),
    '[literal]', NULL
  );
END;

DECLARE
  v_step  CONSTANT bigint  := 100000;  -- 每满 10 万平台积分解锁一档
  v_award CONSTANT integer := 30000;   -- 每档向猫窝基金注入 3 万分（一份猫窝基金）
  v_total bigint;
  v_next  bigint;
  v_added integer := 0;
BEGIN
  SELECT COALESCE(sum(earned_total), 0) INTO v_total FROM public.pet_cat_wallets;

  v_next := (floor(v_total / v_step) + 1) * v_step;
  WHILE v_total >= v_next LOOP
    -- threshold 主键 + ON CONFLICT DO NOTHING：并发发分 / 重放都不会重复注入
    INSERT INTO public.pet_cat_milestones (threshold, awarded)
    VALUES (v_next, v_award)
    ON CONFLICT (threshold) DO NOTHING;
    IF FOUND THEN
      v_added := v_added + 1;
    END IF;
    v_next := v_next + v_step;
  END LOOP;

  RETURN v_added;
END;

DECLARE
  v_src  text;
  v_pts  integer;
BEGIN
  IF NEW.status <> '[literal]' OR coalesce(NEW.buyer_uid, '[literal]') = '[literal]' THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = '[literal]' THEN
    v_src := '[literal]';
  ELSIF TG_TABLE_NAME = '[literal]' THEN
    v_src := '[literal]';
  ELSE
    RETURN NEW;
  END IF;

  v_pts := COALESCE(NEW.total, 0);
  IF v_pts <= 0 THEN
    RETURN NEW;
  END IF;

  -- 幂等发分：同一订单只会真正插入一次流水，冲突时跳过钱包与通知
  INSERT INTO public.pet_cat_point_logs (uid, delta, source, order_id, reason)
  VALUES (NEW.buyer_uid, v_pts, v_src, NEW.id,
          CASE v_src WHEN '[literal]' THEN '[literal]' ELSE '[literal]' END)
  ON CONFLICT (source, order_id) DO NOTHING;

  IF FOUND THEN
    INSERT INTO public.pet_cat_wallets (uid, balance, earned_total)
    VALUES (NEW.buyer_uid, v_pts, v_pts)
    ON CONFLICT (uid) DO UPDATE
      SET balance = pet_cat_wallets.balance + EXCLUDED.balance,
          earned_total = pet_cat_wallets.earned_total + EXCLUDED.earned_total,
          updated_at = now();

    -- 累计上涨后才有可能跨档；结算幂等，多调无害
    PERFORM public.cat_milestone_check();

    PERFORM public.notify_push(
      NEW.buyer_uid, '[literal]', '[literal]',
      format('[literal]', v_pts),
      '[literal]', NEW.id
    );
  END IF;

  RETURN NEW;
END;

DECLARE
  v_uid    text := auth.uid();
  v_key    text := lower(btrim(COALESCE(p_item_key, '[literal]')));
  v_item   public.cat_charity_items%ROWTYPE;
  v_wallet public.pet_cat_wallets%ROWTYPE;
  v_code   text;
  v_left   integer;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_item FROM public.cat_charity_items
   WHERE key = v_key AND enabled;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_wallet FROM public.pet_cat_wallets
   WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND OR v_wallet.balance < v_item.points_cost THEN
    RAISE EXCEPTION '[literal]',
      v_item.points_cost - COALESCE(v_wallet.balance, 0);
  END IF;

  v_left := v_wallet.balance - v_item.points_cost;

  UPDATE public.pet_cat_wallets
     SET balance = v_left, updated_at = now()
   WHERE uid = v_uid;

  v_code := '[literal]' || upper(substr(md5(v_uid || clock_timestamp()::text || random()::text), 1, 8));

  INSERT INTO public.pet_cat_exchanges (uid, item_key, item_name, points_cost, voucher_code)
  VALUES (v_uid, v_item.key, v_item.name, v_item.points_cost, v_code);

  PERFORM public.notify_push(
    v_uid, '[literal]', '[literal]',
    format('[literal]',
           v_item.points_cost, v_item.name, v_code),
    '[literal]', NULL
  );

  RETURN jsonb_build_object(
    '[literal]', v_left,
    '[literal]', jsonb_build_object(
      '[literal]', v_code, '[literal]', v_item.key, '[literal]', v_item.name, '[literal]', v_item.points_cost
    ),
    '[literal]', NULL
  );
END;

DECLARE
  v_uid     text := auth.uid();
  v_name    text := lower(btrim(coalesce(p_to_username, '[literal]')));
  v_my_name text;
  v_to      text;
  v_to_name text;
  v_my      public.pet_cat_wallets%ROWTYPE;
  v_left    integer;
  v_note    text;
  v_pts     integer;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_pts := COALESCE(p_points, 0);
  IF v_pts <= 0 OR v_pts > 10000000 THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_name = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT coalesce(nullif(btrim(p.username), '[literal]'), '[literal]') INTO v_my_name
    FROM public.profiles p WHERE p.uid = v_uid;
  v_my_name := coalesce(v_my_name, '[literal]');

  SELECT p.uid, coalesce(nullif(btrim(p.username), '[literal]'), '[literal]')
    INTO v_to, v_to_name
    FROM public.profiles p
   WHERE lower(btrim(p.username)) = v_name
   LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_to = v_uid THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_my FROM public.pet_cat_wallets
   WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND OR v_my.balance < v_pts THEN
    RAISE EXCEPTION '[literal]',
      v_pts - COALESCE(v_my.balance, 0);
  END IF;

  v_note := left(btrim(coalesce(p_note, '[literal]')), 50);
  v_left := v_my.balance - v_pts;

  UPDATE public.pet_cat_wallets
     SET balance = v_left, updated_at = now()
   WHERE uid = v_uid;

  -- 收款端只涨余额不动 earned_total：平台累计口径保持「真实消费」
  INSERT INTO public.pet_cat_wallets (uid, balance)
  VALUES (v_to, v_pts)
  ON CONFLICT (uid) DO UPDATE
    SET balance = pet_cat_wallets.balance + EXCLUDED.balance,
        updated_at = now();

  INSERT INTO public.pet_cat_transfers (from_uid, from_name, to_uid, to_name, points, note)
  VALUES (v_uid, v_my_name, v_to, v_to_name, v_pts, v_note);

  PERFORM public.notify_push(
    v_uid, '[literal]', '[literal]',
    format('[literal]',
           v_to_name, v_pts, v_left),
    '[literal]', NULL
  );
  PERFORM public.notify_push(
    v_to, '[literal]', '[literal]',
    format('[literal]',
           v_my_name, v_pts,
           CASE WHEN v_note = '[literal]' THEN '[literal]' ELSE '[literal]' || v_note END),
    '[literal]', NULL
  );

  RETURN jsonb_build_object(
    '[literal]', v_left,
    '[literal]', v_to_name,
    '[literal]', v_pts,
    '[literal]', NULL
  );
END;

DECLARE
  v_uid     text := auth.uid();
  v_hidden  boolean := coalesce(p_hidden, true);
  v_ts      timestamptz := CASE WHEN coalesce(p_hidden, true) THEN now() ELSE NULL END;
  v_thread  public.chat_threads%ROWTYPE;
  v_is_user boolean;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF p_thread_id IS NULL THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_thread FROM public.chat_threads WHERE id = p_thread_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_is_user := (v_thread.user_uid = v_uid);
  IF NOT v_is_user AND v_thread.peer_uid <> v_uid THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  UPDATE public.chat_threads
     SET user_hidden_at = CASE WHEN v_is_user THEN v_ts ELSE user_hidden_at END,
         peer_hidden_at = CASE WHEN v_is_user THEN peer_hidden_at ELSE v_ts END
   WHERE id = p_thread_id
  RETURNING * INTO v_thread;

  RETURN jsonb_build_object(
    '[literal]', v_hidden,
    '[literal]', CASE WHEN v_is_user THEN v_thread.user_hidden_at ELSE v_thread.peer_hidden_at END,
    '[literal]', to_jsonb(v_thread)
  );
END;

DECLARE
  v_uid       text := auth.uid();
  v_type      text := btrim(coalesce(p_topic_type, '[literal]'));
  v_peer      text := btrim(coalesce(p_peer_uid, '[literal]'));
  v_title     text := btrim(coalesce(p_topic_title, '[literal]'));
  v_peer_name text := btrim(coalesce(p_peer_name, '[literal]'));
  v_peer_role text := coalesce(nullif(btrim(p_peer_role), '[literal]'), '[literal]');
  v_my_name   text;
  v_row       public.chat_threads%ROWTYPE;
  v_inserted  integer := 0;
  v_restored  boolean := false;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_type = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_peer = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_peer = v_uid THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT coalesce(nullif(btrim(p.username), '[literal]'), '[literal]') INTO v_my_name
    FROM public.profiles p WHERE p.uid = v_uid;
  v_my_name := coalesce(v_my_name, '[literal]');

  IF v_peer_name = '[literal]' THEN
    SELECT coalesce(nullif(btrim(p.username), '[literal]'), '[literal]') INTO v_peer_name
      FROM public.profiles p WHERE p.uid = v_peer;
    v_peer_name := coalesce(v_peer_name, '[literal]');
  END IF;

  -- 幂等一：同话题 + 同参与者（不分方向）已存在 → 直接复用，并清掉我这一侧的隐藏
  SELECT * INTO v_row
    FROM public.chat_threads t
   WHERE t.topic_type = v_type
     AND coalesce(t.topic_id, 0) = coalesce(p_topic_id, 0)
     AND ((t.user_uid = v_uid AND t.peer_uid = v_peer)
       OR (t.user_uid = v_peer AND t.peer_uid = v_uid));
  IF FOUND THEN
    v_restored := (v_row.user_uid = v_uid AND v_row.user_hidden_at IS NOT NULL)
               OR (v_row.peer_uid = v_uid AND v_row.peer_hidden_at IS NOT NULL);
    IF v_restored THEN
      UPDATE public.chat_threads
         SET user_hidden_at = CASE WHEN user_uid = v_uid THEN NULL ELSE user_hidden_at END,
             peer_hidden_at = CASE WHEN peer_uid = v_uid THEN NULL ELSE peer_hidden_at END
       WHERE id = v_row.id
      RETURNING * INTO v_row;
    END IF;
    RETURN jsonb_build_object('[literal]', false, '[literal]', v_restored, '[literal]', to_jsonb(v_row));
  END IF;

  -- 幂等二：并发下同方向同时开会话，唯一索引兜底（冲突时 ROW_COUNT = 0）
  INSERT INTO public.chat_threads (
    topic_type, topic_id, topic_title, user_uid, user_name, peer_uid, peer_name, peer_role
  ) VALUES (
    v_type, p_topic_id, v_title, v_uid, v_my_name, v_peer, v_peer_name, v_peer_role
  )
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  SELECT * INTO v_row
    FROM public.chat_threads t
   WHERE t.topic_type = v_type
     AND coalesce(t.topic_id, 0) = coalesce(p_topic_id, 0)
     AND ((t.user_uid = v_uid AND t.peer_uid = v_peer)
       OR (t.user_uid = v_peer AND t.peer_uid = v_uid));
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  RETURN jsonb_build_object('[literal]', v_inserted > 0, '[literal]', false, '[literal]', to_jsonb(v_row));
END;

DECLARE
  v_ref     bigint := coalesce(p_ref_id, 0);
  v_enabled boolean := coalesce(p_enabled, true);
BEGIN
