declare j public.file_generation_jobs; v_credits bigint; v_inserted bigint; v_error text;
begin
  perform public._file_generation_expire(p_uid);
  select * into j from public.file_generation_jobs where uid = p_uid and id = p_job_id for update;
  if not found then return jsonb_build_object('[literal]', false, '[literal]', '[literal]'); end if;
  if p_input_hash is null or j.input_hash <> p_input_hash then return jsonb_build_object('[literal]', false, '[literal]', '[literal]'); end if;
  if j.status = '[literal]' then return jsonb_build_object('[literal]', true, '[literal]', j.id, '[literal]', j.status, '[literal]', j.questions); end if;
  if j.status <> '[literal]' then return jsonb_build_object('[literal]', false, '[literal]', case j.status when '[literal]' then '[literal]' else '[literal]' end, '[literal]', true); end if;
  v_error := p_error_code;
  if v_error is null then
    if p_questions is null or jsonb_typeof(p_questions) <> '[literal]' then v_error := '[literal]';
    elsif jsonb_array_length(p_questions) <> j.questions_per_job then v_error := '[literal]'; end if;
  end if;
  if v_error is not null then
    if length(v_error) not between 1 and 64 or v_error !~ '[literal]' then v_error := '[literal]'; end if;
    select credits into v_credits from public.file_generation_accounts where uid = p_uid for update;
    insert into public.file_generation_ledger(uid, job_id, kind, credits_delta, balance_after)
      values(p_uid, j.id, '[literal]', 1, v_credits + 1) on conflict (job_id, kind) do nothing returning id into v_inserted;
    if v_inserted is not null then update public.file_generation_accounts set credits = credits + 1, updated_at = now() where uid = p_uid; end if;
    update public.file_generation_jobs set status = '[literal]', error_code = v_error, updated_at = now() where id = j.id;
    return jsonb_build_object('[literal]', false, '[literal]', '[literal]', '[literal]', true);
  end if;
  update public.file_generation_jobs set status = '[literal]', questions = p_questions, updated_at = now() where id = j.id;
  return jsonb_build_object('[literal]', true, '[literal]', j.id, '[literal]', '[literal]', '[literal]', p_questions);
end

declare previous public.file_generation_ledger; v_credits bigint;
begin
  if p_payment_provider is null or p_payment_provider not in ('[literal]', '[literal]', '[literal]', '[literal]')
    or p_verified_payment_ref is null or length(p_verified_payment_ref) not between 1 and 200 or p_verified_payment_ref ~* '[literal]' 
    or p_credits is null or p_credits not between 1 and 10000
    or p_quoted_price_cent is null or p_quoted_price_cent not between 1 and 1000000
    or p_verified_amount_cent is null or p_verified_amount_cent <> p_quoted_price_cent * p_credits then raise exception '[literal]'; end if;
  perform public._file_generation_expire(p_uid);
  select * into previous from public.file_generation_ledger where payment_provider = p_payment_provider and verified_payment_ref = p_verified_payment_ref;
  if found then
    if previous.uid <> p_uid or previous.credits_delta <> p_credits or previous.verified_amount_cent <> p_verified_amount_cent or previous.quoted_price_cent <> p_quoted_price_cent then raise exception '[literal]'; end if;
    select credits into v_credits from public.file_generation_accounts where uid = p_uid;
    return jsonb_build_object('[literal]', true, '[literal]', true, '[literal]', v_credits);
  end if;
  select credits into v_credits from public.file_generation_accounts where uid = p_uid for update;
  update public.file_generation_accounts set credits = credits + p_credits, updated_at = now() where uid = p_uid;
  insert into public.file_generation_ledger(uid, kind, credits_delta, balance_after, payment_provider, verified_payment_ref, verified_amount_cent, quoted_price_cent)
    values(p_uid, '[literal]', p_credits, v_credits + p_credits, p_payment_provider, p_verified_payment_ref, p_verified_amount_cent, p_quoted_price_cent);
  return jsonb_build_object('[literal]', true, '[literal]', false, '[literal]', v_credits + p_credits);
end

declare j public.file_generation_jobs;
begin
  perform public._file_generation_expire(p_uid);
  select * into j from public.file_generation_jobs where uid = p_uid and request_id = p_request_id;
  if not found then return jsonb_build_object('[literal]', false, '[literal]', '[literal]'); end if;
  if j.status in ('[literal]', '[literal]') then return jsonb_build_object('[literal]', false, '[literal]', case j.status when '[literal]' then '[literal]' else '[literal]' end); end if;
  return jsonb_build_object('[literal]', true, '[literal]', j.id, '[literal]', j.request_id, '[literal]', j.status,
    '[literal]', j.file_name, '[literal]', j.subject, '[literal]', j.questions_per_job, '[literal]', j.questions);
end

declare j public.file_generation_jobs; v_credits bigint;
begin
  if p_request_id is null or p_input_hash is null or p_input_hash !~ '[literal]' or p_price_cent is null or p_price_cent <= 0
     or p_questions_per_job is null or p_questions_per_job not between 3 and 10
     or p_file_name is null or length(p_file_name) not between 1 and 160
     or p_subject is null or length(p_subject) not between 1 and 40 then raise exception '[literal]'; end if;
  perform public._file_generation_expire(p_uid);
  select * into j from public.file_generation_jobs where uid = p_uid and request_id = p_request_id for update;
  if found then
    if j.input_hash <> p_input_hash then return jsonb_build_object('[literal]', false, '[literal]', '[literal]'); end if;
    if j.status = '[literal]' then return jsonb_build_object('[literal]', true, '[literal]', j.id, '[literal]', j.status, '[literal]', j.questions); end if;
    return jsonb_build_object('[literal]', false, '[literal]', case j.status when '[literal]' then '[literal]' when '[literal]' then '[literal]' else '[literal]' end,
      '[literal]', j.id, '[literal]', j.status <> '[literal]');
  end if;
  select credits into v_credits from public.file_generation_accounts where uid = p_uid for update;
  if v_credits < 1 then return jsonb_build_object('[literal]', false, '[literal]', '[literal]'); end if;
  insert into public.file_generation_jobs(uid, request_id, input_hash, price_cent, questions_per_job, file_name, subject, status, lease_expires_at)
    values(p_uid, p_request_id, p_input_hash, p_price_cent, p_questions_per_job, p_file_name, p_subject, '[literal]', clock_timestamp() + interval '[literal]') returning * into j;
  update public.file_generation_accounts set credits = credits - 1, updated_at = now() where uid = p_uid;
  insert into public.file_generation_ledger(uid, job_id, kind, credits_delta, balance_after)
    values(p_uid, j.id, '[literal]', -1, v_credits - 1);
  return jsonb_build_object('[literal]', true, '[literal]', true, '[literal]', j.id, '[literal]', '[literal]', '[literal]', j.questions_per_job);
end

declare v_credits bigint;
