DECLARE
  v_app     public.partner_apps%ROWTYPE;
  v_uid     text := auth.uid();
  v_store   bigint;
  v_name    text;
  v_contact text;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF NOT public.is_super_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_app FROM public.partner_apps WHERE id = p_app_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF p_ok AND EXISTS (
    SELECT 1 FROM public.shop_stores s WHERE s.owner_uid = v_app.creator_uid
      AND (s.operation_revoked OR s.status = '[literal]')
  ) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  UPDATE public.partner_apps
     SET status     = CASE WHEN p_ok THEN '[literal]' ELSE '[literal]' END,
         reply      = coalesce(btrim(p_reply), '[literal]'),
         handled_at = now()
   WHERE id = p_app_id;

  IF p_ok THEN
    IF coalesce(btrim(v_app.creator_uid), '[literal]') = '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;

    -- 幂等一：该申请已建过店
    SELECT id INTO v_store FROM public.shop_stores WHERE partner_app_id = p_app_id;
    -- 幂等二：该同学已有一间店（历史手工创建或曾用其他申请开过），直接复用
    IF v_store IS NULL THEN
      SELECT id INTO v_store FROM public.shop_stores WHERE owner_uid = v_app.creator_uid;
    END IF;

    IF v_store IS NULL THEN
      v_name := coalesce(nullif(btrim(v_app.name), '[literal]'), '[literal]');
      v_contact := coalesce(nullif(btrim(v_app.wechat), '[literal]'), coalesce(btrim(v_app.phone), '[literal]'));

      -- 申请时上传的店铺图片与介绍在此带入店铺资料（单图 → 门头图；介绍 → 店铺简介）
      INSERT INTO public.shop_stores (
        owner_uid, partner_app_id, name, emoji, cover_url, description,
        campus, building, room, contact, notice, sort
      ) VALUES (
        v_app.creator_uid, p_app_id, v_name, '[literal]',
        coalesce(btrim(v_app.image), '[literal]'), coalesce(btrim(v_app.description), '[literal]'),
        coalesce(btrim(v_app.campus), '[literal]'), coalesce(btrim(v_app.building), '[literal]'),
        coalesce(btrim(v_app.room), '[literal]'), v_contact,
        '[literal]', 100
      )
      RETURNING id INTO v_store;
    ELSE
      -- 复用已有店铺时补上溯源头，方便日后对账（不覆盖店主已维护的图片/介绍）
      UPDATE public.shop_stores
         SET partner_app_id = p_app_id
       WHERE id = v_store AND partner_app_id IS NULL;
      SELECT name INTO v_name FROM public.shop_stores WHERE id = v_store;
    END IF;

    PERFORM public.notify_push(
      v_app.creator_uid, '[literal]', '[literal]',
      format('[literal]', coalesce(v_name, '[literal]')),
      '[literal]', p_app_id
    );
  ELSE
    PERFORM public.notify_push(
      v_app.creator_uid, '[literal]', '[literal]',
      coalesce(nullif(btrim(p_reply), '[literal]'), '[literal]'),
      '[literal]', p_app_id
    );
  END IF;

  RETURN jsonb_build_object(
    '[literal]', p_ok,
    '[literal]', v_store,
    '[literal]', p_app_id
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_action text := lower(btrim(COALESCE(p_action, '[literal]')));
  v_item text := lower(btrim(COALESCE(p_item, '[literal]')));
  v_row public.pet_profiles%ROWTYPE;
  v_now timestamptz := now();
  v_day date := (now() AT TIME ZONE '[literal]')::date;
  v_cd integer;
  v_last timestamptz;
  v_sat integer;
  v_clean integer;
  v_mood integer;
  v_exp integer := 0;
  v_int integer := 0;
  v_qty integer;
  v_gain jsonb;
  v_codes text[] := ARRAY[]::text[];
  v_new text[];
  v_today integer;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_action NOT IN ('[literal]', '[literal]', '[literal]', '[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  PERFORM public.pet_settle(v_uid);
  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 冷却（服务端裁决）
  v_cd := CASE v_action
            WHEN '[literal]' THEN 180
            WHEN '[literal]' THEN 600
            WHEN '[literal]' THEN 1200
            WHEN '[literal]' THEN 30
            ELSE 60
          END;
  v_last := NULLIF(v_row.last_action_at ->> v_action, '[literal]')::timestamptz;
  IF v_last IS NOT NULL AND v_now < v_last + make_interval(secs => v_cd) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 道具校验与消耗
  IF v_item <> '[literal]' THEN
    IF v_item NOT IN ('[literal]', '[literal]', '[literal]', '[literal]') THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    IF (CASE v_item
          WHEN '[literal]' THEN '[literal]'
          WHEN '[literal]' THEN '[literal]'
          WHEN '[literal]' THEN '[literal]'
          ELSE '[literal]'
        END) <> v_action THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    v_qty := COALESCE((v_row.inventory ->> v_item)::integer, 0);
    IF v_qty <= 0 THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    UPDATE public.pet_profiles
       SET inventory = jsonb_set(inventory, ARRAY[v_item], to_jsonb(v_qty - 1), true)
     WHERE uid = v_uid;
  END IF;

  v_sat := v_row.satiation;
  v_clean := v_row.cleanliness;
  v_mood := v_row.mood;

  CASE v_action
    WHEN '[literal]' THEN
      IF v_item = '[literal]' THEN
        v_sat := v_sat + 25; v_int := 1; v_exp := 12;
      ELSIF v_item = '[literal]' THEN
        v_sat := v_sat + 40; v_mood := v_mood + 8; v_int := 2; v_exp := 18;
      ELSE
        v_sat := v_sat + 20; v_mood := v_mood + 5; v_int := 1; v_exp := 6;
      END IF;
    WHEN '[literal]' THEN
      IF v_item = '[literal]' THEN
        v_clean := v_clean + 35; v_mood := v_mood + 3; v_int := 1; v_exp := 12;
      ELSE
        v_clean := v_clean + 25; v_mood := v_mood + 5; v_int := 1; v_exp := 6;
      END IF;
    WHEN '[literal]' THEN
      IF v_item = '[literal]' THEN
        v_mood := v_mood + 30; v_sat := v_sat - 4; v_clean := v_clean - 6; v_int := 3; v_exp := 15;
      ELSE
        v_mood := v_mood + 20; v_sat := v_sat - 3; v_clean := v_clean - 5; v_int := 2; v_exp := 8;
      END IF;
    WHEN '[literal]' THEN
      v_mood := v_mood + 6; v_int := 1; v_exp := 2;
    ELSE
      v_mood := v_mood + 5; v_int := 1; v_exp := 3;
  END CASE;

  UPDATE public.pet_profiles
     SET satiation = GREATEST(0, LEAST(100, v_sat)),
         cleanliness = GREATEST(0, LEAST(100, v_clean)),
         mood = GREATEST(0, LEAST(100, v_mood)),
         last_action_at = jsonb_set(COALESCE(last_action_at, '[literal]'::jsonb), ARRAY[v_action], to_jsonb(v_now)),
         total_interactions = total_interactions + 1
   WHERE uid = v_uid;

  v_gain := public.pet_gain(v_uid, v_exp, 0, v_int);

  INSERT INTO public.pet_actions (uid, action, exp_delta, coin_delta, payload, day)
  VALUES (v_uid, v_action, v_exp, 0, jsonb_build_object('[literal]', v_item), v_day);

  SELECT count(*) INTO v_today FROM public.pet_actions
   WHERE uid = v_uid AND day = v_day AND action IN ('[literal]', '[literal]', '[literal]', '[literal]', '[literal]');

  IF v_today >= 10 THEN v_codes := array_append(v_codes, '[literal]'); END IF;
  IF v_today >= 30 THEN v_codes := array_append(v_codes, '[literal]'); END IF;
  IF v_row.total_interactions + 1 >= 50 THEN v_codes := array_append(v_codes, '[literal]'); END IF;
  IF COALESCE((v_gain ->> '[literal]')::integer, 1) >= 5 THEN v_codes := array_append(v_codes, '[literal]'); END IF;
  IF COALESCE((v_gain ->> '[literal]')::integer, 1) >= 10 THEN v_codes := array_append(v_codes, '[literal]'); END IF;

  v_new := public.pet_unlock_many(v_uid, v_codes);

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', jsonb_build_object('[literal]', v_exp, '[literal]', 0, '[literal]', v_int),
    '[literal]', COALESCE((v_gain ->> '[literal]')::integer, v_row.level) > v_row.level,
    '[literal]', jsonb_build_object(
      '[literal]', to_jsonb(v_new),
      '[literal]', COALESCE(v_gain -> '[literal]', '[literal]'::jsonb)
    )
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_item text := lower(btrim(COALESCE(p_item, '[literal]')));
  v_price integer;
  v_row public.pet_profiles%ROWTYPE;
  v_inv jsonb;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_price := CASE v_item
               WHEN '[literal]' THEN 8
               WHEN '[literal]' THEN 18
               WHEN '[literal]' THEN 10
               WHEN '[literal]' THEN 20
               ELSE 0
             END;
  IF v_price = 0 THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_row.coins < v_price THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_inv := jsonb_set(COALESCE(v_row.inventory, '[literal]'::jsonb), ARRAY[v_item],
                     to_jsonb(COALESCE((v_row.inventory ->> v_item)::integer, 0) + 1), true);

  UPDATE public.pet_profiles
     SET coins = coins - v_price, inventory = v_inv
   WHERE uid = v_uid;

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', jsonb_build_object('[literal]', 0, '[literal]', -v_price, '[literal]', 0),
    '[literal]', jsonb_build_object('[literal]', '[literal]'::jsonb, '[literal]', '[literal]'::jsonb)
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_level integer := COALESCE(p_level, 0);
  v_row public.pet_profiles%ROWTYPE;
  v_claimed integer[];
  v_tickets integer;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_level NOT IN (5, 10, 20) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_row.level < v_level THEN
    RAISE EXCEPTION '[literal]', v_level;
  END IF;

  v_claimed := COALESCE(v_row.level_rewards_claimed, ARRAY[]::integer[]);
  IF v_level = ANY (v_claimed) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_tickets := COALESCE(v_row.gacha_tickets, 0) + 1;

  UPDATE public.pet_profiles
     SET level_rewards_claimed = v_claimed || v_level,
         gacha_tickets = v_tickets,
         updated_at = now()
   WHERE uid = v_uid;

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', v_level,
    '[literal]', v_tickets,
    '[literal]', jsonb_build_object('[literal]', 0, '[literal]', 0, '[literal]', 0, '[literal]', '[literal]'::jsonb),
    '[literal]', jsonb_build_object('[literal]', '[literal]'::jsonb, '[literal]', '[literal]'::jsonb),
    '[literal]', NULL
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_quest text := lower(btrim(COALESCE(p_quest, '[literal]')));
  v_day date := (now() AT TIME ZONE '[literal]')::date;
  v_row public.pet_profiles%ROWTYPE;
  v_prog integer := 0;
  v_need integer := 1;
  v_exp integer;
  v_coins integer;
  v_item text;
  v_items jsonb := '[literal]'::jsonb;
  v_gain jsonb;
  v_new text[];
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_exp := CASE v_quest
             WHEN '[literal]' THEN 15
             WHEN '[literal]' THEN 8
             WHEN '[literal]' THEN 12
             ELSE 0
           END;
  v_coins := CASE v_quest
               WHEN '[literal]' THEN 10
               WHEN '[literal]' THEN 6
               WHEN '[literal]' THEN 8
               ELSE 0
             END;
  v_item := CASE v_quest
              WHEN '[literal]' THEN '[literal]'
              WHEN '[literal]' THEN '[literal]'
              WHEN '[literal]' THEN '[literal]'
              ELSE '[literal]'
            END;
  IF v_exp = 0 THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  PERFORM public.pet_settle(v_uid);
  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_quest = '[literal]' THEN
    v_need := 3;
    SELECT count(*) INTO v_prog FROM public.pet_actions
     WHERE uid = v_uid AND day = v_day AND action IN ('[literal]', '[literal]', '[literal]', '[literal]');
  ELSIF v_quest = '[literal]' THEN
    v_need := 1;
    SELECT count(*) INTO v_prog FROM public.pet_actions
     WHERE uid = v_uid AND day = v_day AND action = '[literal]';
  ELSE
    v_need := 1;
    SELECT count(*) INTO v_prog FROM public.pet_actions
     WHERE uid = v_uid AND day = v_day AND dedupe_key LIKE '[literal]';
  END IF;

  IF v_prog < v_need THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  BEGIN
    INSERT INTO public.pet_actions (uid, action, exp_delta, coin_delta, dedupe_key, day)
    VALUES (v_uid, '[literal]' || v_quest, v_exp, v_coins,
            '[literal]' || v_quest || '[literal]' || v_day::text, v_day);
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION '[literal]';
  END;

  IF v_item <> '[literal]' THEN
    PERFORM public.pet_item_add(v_uid, v_item, 1, '[literal]' || v_quest);
    v_items := jsonb_set(v_items, ARRAY[v_item], to_jsonb(1), true);
  END IF;

  v_gain := public.pet_gain(v_uid, v_exp, v_coins, 1);
  v_new := public.pet_unlock_many(v_uid, ARRAY['[literal]']);
  IF COALESCE((v_gain ->> '[literal]')::integer, 1) >= 5 THEN
    v_new := v_new || public.pet_unlock_many(v_uid, ARRAY['[literal]']);
  END IF;
  IF COALESCE((v_gain ->> '[literal]')::integer, 1) >= 10 THEN
    v_new := v_new || public.pet_unlock_many(v_uid, ARRAY['[literal]']);
  END IF;

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', jsonb_build_object('[literal]', v_exp, '[literal]', v_coins, '[literal]', 1, '[literal]', v_items),
    '[literal]', COALESCE((v_gain ->> '[literal]')::integer, 1) > v_row.level,
    '[literal]', jsonb_build_object(
      '[literal]', to_jsonb(v_new),
      '[literal]', COALESCE(v_gain -> '[literal]', '[literal]'::jsonb)
    )
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_day date := (now() AT TIME ZONE '[literal]')::date;
  v_row public.pet_profiles%ROWTYPE;
  v_streak integer;
  v_coins integer;
  v_exp integer;
  v_inv jsonb;
  v_gain jsonb;
  v_codes text[] := ARRAY[]::text[];
  v_new text[];
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  PERFORM public.pet_settle(v_uid);
  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  BEGIN
    INSERT INTO public.pet_actions (uid, action, dedupe_key, day)
    VALUES (v_uid, '[literal]', '[literal]' || v_day::text, v_day);
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION '[literal]';
  END;

  v_streak := CASE WHEN v_row.last_signin_day = v_day - 1 THEN v_row.signin_streak + 1 ELSE 1 END;
  v_coins := 10 + LEAST(v_streak, 7) * 3;
  v_exp := 15 + LEAST(v_streak, 7) * 2;

  v_inv := COALESCE(v_row.inventory, '[literal]'::jsonb);
  v_inv := jsonb_set(v_inv, ARRAY['[literal]'],
                     to_jsonb(COALESCE((v_inv ->> '[literal]')::integer, 0) + 1), true);
  IF v_streak % 7 = 0 THEN
    v_inv := jsonb_set(v_inv, ARRAY['[literal]'],
                       to_jsonb(COALESCE((v_inv ->> '[literal]')::integer, 0) + 1), true);
  END IF;

  UPDATE public.pet_profiles
     SET last_signin_day = v_day,
         signin_streak = v_streak,
         inventory = v_inv
   WHERE uid = v_uid;

  v_gain := public.pet_gain(v_uid, v_exp, v_coins, 1);

  v_codes := array_append(v_codes, '[literal]');
  IF v_streak >= 3 THEN v_codes := array_append(v_codes, '[literal]'); END IF;
  IF v_streak >= 7 THEN v_codes := array_append(v_codes, '[literal]'); END IF;
  IF v_streak >= 30 THEN v_codes := array_append(v_codes, '[literal]'); END IF;
  IF COALESCE((v_gain ->> '[literal]')::integer, 1) >= 5 THEN v_codes := array_append(v_codes, '[literal]'); END IF;
  IF COALESCE((v_gain ->> '[literal]')::integer, 1) >= 10 THEN v_codes := array_append(v_codes, '[literal]'); END IF;

  v_new := public.pet_unlock_many(v_uid, v_codes);

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', v_streak,
    '[literal]', jsonb_build_object('[literal]', v_exp, '[literal]', v_coins, '[literal]', 1),
    '[literal]', COALESCE((v_gain ->> '[literal]')::integer, 1) > v_row.level,
    '[literal]', jsonb_build_object(
      '[literal]', to_jsonb(v_new),
      '[literal]', COALESCE(v_gain -> '[literal]', '[literal]'::jsonb)
    )
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_image text := btrim(COALESCE(p_image, '[literal]'));
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF char_length(v_image) > 512 THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  -- 非空时只接受 https 直链：避免存入 javascript:/data: 之类的地址，也避免页面出现混合内容告警
  IF v_image <> '[literal]' AND v_image !~* '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.pet_profiles WHERE uid = v_uid) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  UPDATE public.pet_profiles
     SET custom_image = v_image,
         updated_at = now()
   WHERE uid = v_uid;

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', jsonb_build_object('[literal]', 0, '[literal]', 0, '[literal]', 0),
    '[literal]', jsonb_build_object('[literal]', '[literal]'::jsonb, '[literal]', '[literal]'::jsonb)
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_kind text := lower(btrim(COALESCE(p_kind, '[literal]')));
  v_key text := btrim(COALESCE(p_key, '[literal]'));
  v_row public.pet_profiles%ROWTYPE;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_kind = '[literal]' THEN
    IF NOT (v_key = ANY (v_row.unlocked_skins)) THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    UPDATE public.pet_profiles SET equipped_skin = v_key WHERE uid = v_uid;
  ELSIF v_kind = '[literal]' THEN
    IF public.pet_title_level(v_key) > 100 THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    IF v_row.level < public.pet_title_level(v_key) THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    UPDATE public.pet_profiles SET equipped_title = v_key WHERE uid = v_uid;
  ELSE
    RAISE EXCEPTION '[literal]';
  END IF;

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', jsonb_build_object('[literal]', 0, '[literal]', 0, '[literal]', 0),
    '[literal]', jsonb_build_object('[literal]', '[literal]'::jsonb, '[literal]', '[literal]'::jsonb)
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_key text := lower(btrim(COALESCE(p_reward_key, '[literal]')));
  v_need integer;
  v_name text;
  v_row public.pet_profiles%ROWTYPE;
  v_shards integer;
  v_code text := '[literal]';
  v_skins text[];
  v_titles text[];
  v_new_skins text[] := ARRAY[]::text[];
  v_new_titles text[] := ARRAY[]::text[];
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_need := CASE v_key
              WHEN '[literal]' THEN 10
              WHEN '[literal]' THEN 6
              WHEN '[literal]' THEN 12
              ELSE 0
            END;
  v_name := CASE v_key
              WHEN '[literal]' THEN '[literal]'
              WHEN '[literal]' THEN '[literal]'
              WHEN '[literal]' THEN '[literal]'
              ELSE '[literal]'
            END;
  IF v_need = 0 THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_shards := COALESCE(v_row.shard_progress, 0);
  IF v_shards < v_need THEN
    RAISE EXCEPTION '[literal]', v_need - v_shards;
  END IF;

  v_skins := COALESCE(v_row.unlocked_skins, ARRAY['[literal]']);
  v_titles := COALESCE(v_row.unlocked_titles, ARRAY[]::text[]);

  IF v_key = '[literal]' AND '[literal]' = ANY (v_titles) THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_key = '[literal]' AND '[literal]' = ANY (v_skins) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_key = '[literal]' THEN
    v_skins := array_append(v_skins, '[literal]');
    v_new_skins := ARRAY['[literal]'];
  ELSIF v_key = '[literal]' THEN
    v_titles := array_append(v_titles, '[literal]');
    v_new_titles := ARRAY['[literal]'];
  END IF;

  v_code := '[literal]' || upper(substr(md5(v_uid || clock_timestamp()::text || random()::text), 1, 8));

  UPDATE public.pet_profiles
     SET shard_progress = v_shards - v_need,
         unlocked_skins = v_skins,
         unlocked_titles = v_titles,
         updated_at = now()
   WHERE uid = v_uid;

  INSERT INTO public.pet_exchanges (uid, reward_key, reward_name, voucher_code)
  VALUES (v_uid, v_key, v_name, v_code);

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', jsonb_build_object('[literal]', v_code, '[literal]', v_key, '[literal]', v_name),
    '[literal]', jsonb_build_object('[literal]', 0, '[literal]', 0, '[literal]', 0, '[literal]', '[literal]'::jsonb),
    '[literal]', jsonb_build_object(
      '[literal]', '[literal]'::jsonb,
      '[literal]', to_jsonb(v_new_skins),
      '[literal]', to_jsonb(v_new_titles)
    ),
    '[literal]', NULL
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_source text := lower(btrim(COALESCE(p_source, '[literal]')));
  v_row public.pet_profiles%ROWTYPE;
  v_roll integer;
  v_kind text;
  v_key text := '[literal]';
  v_amount integer := 0;
  v_rarity text := '[literal]';
  v_name text := '[literal]';
  v_skins text[];
  v_titles text[];
  v_candidates text[];
  v_gain jsonb;
  v_tickets integer;
  v_items jsonb := '[literal]'::jsonb;
  v_new_skins text[] := ARRAY[]::text[];
  v_new_titles text[] := ARRAY[]::text[];
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_source NOT IN ('[literal]', '[literal]', '[literal]') THEN
    v_source := '[literal]';
  END IF;

  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF COALESCE(v_row.gacha_tickets, 0) <= 0 THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_skins := COALESCE(v_row.unlocked_skins, ARRAY['[literal]']);
  v_titles := COALESCE(v_row.unlocked_titles, ARRAY[]::text[]);
  v_roll := floor(random() * 100)::integer;

  IF v_roll < 45 THEN
    v_kind := '[literal]';
    v_amount := 30 + floor(random() * 50)::integer;
    v_key := '[literal]';
    v_name := '[literal]';
    v_rarity := CASE WHEN v_amount >= 70 THEN '[literal]' ELSE '[literal]' END;
  ELSIF v_roll < 85 THEN
    v_kind := '[literal]';
    v_key := (ARRAY['[literal]', '[literal]', '[literal]', '[literal]'])[1 + floor(random() * 4)::integer];
    v_amount := CASE WHEN v_key = '[literal]' THEN 2 ELSE 1 END;
    v_name := CASE v_key
                WHEN '[literal]' THEN '[literal]'
                WHEN '[literal]' THEN '[literal]'
                WHEN '[literal]' THEN '[literal]'
                ELSE '[literal]'
              END;
    v_rarity := CASE WHEN v_key IN ('[literal]', '[literal]') THEN '[literal]' ELSE '[literal]' END;
  ELSIF v_roll < 96 THEN
    SELECT array_agg(k) INTO v_candidates
      FROM unnest(ARRAY['[literal]', '[literal]', '[literal]']) AS k
     WHERE NOT (k = ANY (v_skins));
    IF v_candidates IS NULL OR array_length(v_candidates, 1) IS NULL THEN
      v_kind := '[literal]'; v_key := '[literal]'; v_amount := 100; v_name := '[literal]'; v_rarity := '[literal]';
    ELSE
      v_kind := '[literal]';
      v_key := v_candidates[1 + floor(random() * array_length(v_candidates, 1))::integer];
      v_name := CASE v_key WHEN '[literal]' THEN '[literal]' WHEN '[literal]' THEN '[literal]' ELSE '[literal]' END;
      v_rarity := '[literal]';
      v_skins := array_append(v_skins, v_key);
      v_new_skins := ARRAY[v_key];
    END IF;
  ELSE
    IF '[literal]' = ANY (v_titles) THEN
      v_kind := '[literal]'; v_key := '[literal]'; v_amount := 80; v_name := '[literal]'; v_rarity := '[literal]';
    ELSE
      v_kind := '[literal]'; v_key := '[literal]'; v_name := '[literal]'; v_rarity := '[literal]';
      v_titles := array_append(v_titles, v_key);
      v_new_titles := ARRAY[v_key];
    END IF;
  END IF;

  v_tickets := GREATEST(0, COALESCE(v_row.gacha_tickets, 0) - 1);

  UPDATE public.pet_profiles
     SET gacha_tickets = v_tickets,
         unlocked_skins = CASE WHEN array_length(v_new_skins, 1) IS NULL THEN unlocked_skins ELSE v_skins END,
         unlocked_titles = v_titles,
         updated_at = now()
   WHERE uid = v_uid;

  v_gain := public.pet_gain(v_uid, 0, CASE WHEN v_kind = '[literal]' THEN v_amount ELSE 0 END, 0);

  IF v_kind = '[literal]' THEN
    PERFORM public.pet_item_add(v_uid, v_key, v_amount, '[literal]');
    v_items := jsonb_set(v_items, ARRAY[v_key], to_jsonb(v_amount), true);
  END IF;

  INSERT INTO public.pet_gacha_draws (uid, source, prize_kind, prize_key, prize_amount, rarity)
  VALUES (v_uid, v_source, v_kind, v_key, v_amount, v_rarity);

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', jsonb_build_object('[literal]', v_kind, '[literal]', v_key, '[literal]', v_name, '[literal]', v_amount, '[literal]', v_rarity),
    '[literal]', v_tickets,
    '[literal]', jsonb_build_object(
      '[literal]', 0,
      '[literal]', CASE WHEN v_kind = '[literal]' THEN v_amount ELSE 0 END,
      '[literal]', 0,
      '[literal]', v_items
    ),
    '[literal]', COALESCE((v_gain ->> '[literal]')::integer, 1) > v_row.level,
    '[literal]', jsonb_build_object(
      '[literal]', '[literal]'::jsonb,
      '[literal]', to_jsonb(v_new_skins),
      '[literal]', to_jsonb(v_new_titles)
    ),
    '[literal]', NULL
  );
END;

DECLARE
  v_row public.pet_profiles%ROWTYPE;
  v_level integer;
  v_exp integer;
  v_need integer;
  v_stage text;
  v_skins text[];
  v_new_skins text[] := ARRAY[]::text[];
  v_key text;
BEGIN
  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = p_uid FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('[literal]', 1, '[literal]', 0, '[literal]', '[literal]', '[literal]', '[literal]'::jsonb);
  END IF;

  v_level := v_row.level;
  v_exp := GREATEST(0, v_row.exp + COALESCE(p_exp, 0));
  v_skins := v_row.unlocked_skins;

  WHILE v_level < 60 LOOP
    v_need := public.pet_exp_need(v_level);
    EXIT WHEN v_exp < v_need;
    v_exp := v_exp - v_need;
    v_level := v_level + 1;
    FOREACH v_key IN ARRAY ARRAY['[literal]', '[literal]', '[literal]'] LOOP
      IF v_level >= public.pet_skin_level(v_key) AND NOT (v_key = ANY (v_skins)) THEN
        v_skins := array_append(v_skins, v_key);
        v_new_skins := array_append(v_new_skins, v_key);
      END IF;
    END LOOP;
  END LOOP;

  v_stage := public.pet_stage_of(v_level);

  UPDATE public.pet_profiles
     SET level = v_level,
         exp = v_exp,
         stage = v_stage,
         coins = GREATEST(0, coins + COALESCE(p_coins, 0)),
         intimacy = GREATEST(0, LEAST(999, intimacy + COALESCE(p_intimacy, 0))),
         unlocked_skins = v_skins,
         updated_at = now()
   WHERE uid = p_uid;

  RETURN jsonb_build_object(
    '[literal]', v_level,
    '[literal]', v_exp,
    '[literal]', v_stage,
    '[literal]', to_jsonb(v_new_skins)
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_name text := btrim(COALESCE(p_pet_name, '[literal]'));
  v_hit integer;
  v_created boolean;
  v_day date := (now() AT TIME ZONE '[literal]')::date;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_name = '[literal]' THEN v_name := '[literal]'; END IF;
  IF char_length(v_name) > 12 THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  INSERT INTO public.pet_profiles (uid, pet_name) VALUES (v_uid, v_name)
  ON CONFLICT (uid) DO NOTHING;
  GET DIAGNOSTICS v_hit = ROW_COUNT;
  v_created := v_hit > 0;

  IF v_created THEN
    INSERT INTO public.pet_actions (uid, action, payload, dedupe_key, day)
    VALUES (v_uid, '[literal]', '[literal]'::jsonb, '[literal]' || v_uid, v_day);
    PERFORM public.pet_unlock(v_uid, '[literal]');
  END IF;

  PERFORM public.pet_settle(v_uid);

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', v_created,
    '[literal]', jsonb_build_object('[literal]', 0, '[literal]', 0, '[literal]', 0),
    '[literal]', jsonb_build_object(
      '[literal]', CASE WHEN v_created THEN to_jsonb(ARRAY['[literal]']) ELSE '[literal]'::jsonb END,
      '[literal]', '[literal]'::jsonb
    )
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_code text := upper(btrim(COALESCE(p_code, '[literal]')));
  v_day date := (now() AT TIME ZONE '[literal]')::date;
  v_inviter text;
  v_inviter_name text;
  v_row public.pet_profiles%ROWTYPE;
  v_today integer;
  v_inserted integer := 0;
  v_gain jsonb;
  v_items jsonb := '[literal]'::jsonb;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_code = '[literal]' THEN
    RETURN jsonb_build_object('[literal]', '[literal]', '[literal]', NULL);
  END IF;

  SELECT uid, COALESCE(pet_name, '[literal]') INTO v_inviter, v_inviter_name
    FROM public.pet_profiles WHERE invite_code = v_code;

  IF v_inviter IS NULL THEN
    RETURN jsonb_build_object('[literal]', '[literal]', '[literal]', NULL);
  END IF;
  IF v_inviter = v_uid THEN
    RETURN jsonb_build_object('[literal]', '[literal]', '[literal]', v_inviter_name, '[literal]', NULL);
  END IF;

  PERFORM public.pet_settle(v_uid);
  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT count(*) INTO v_today FROM public.pet_invites
   WHERE invitee_uid = v_uid AND day = v_day;
  IF v_today >= 5 THEN
    RETURN jsonb_build_object('[literal]', '[literal]', '[literal]', v_inviter_name, '[literal]', NULL);
  END IF;

  INSERT INTO public.pet_invites (inviter_uid, invitee_uid, code, item_granted, day)
  VALUES (v_inviter, v_uid, v_code, '[literal]', v_day)
  ON CONFLICT (inviter_uid, invitee_uid) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_inserted = 0 THEN
    RETURN jsonb_build_object('[literal]', '[literal]', '[literal]', v_inviter_name, '[literal]', NULL);
  END IF;

  UPDATE public.pet_profiles
     SET shard_progress = COALESCE(shard_progress, 0) + 1,
         updated_at = now()
   WHERE uid = v_inviter;

  PERFORM public.pet_item_add(v_uid, '[literal]', 1, '[literal]');
  v_items := jsonb_set(v_items, ARRAY['[literal]'], to_jsonb(1), true);
  v_gain := public.pet_gain(v_uid, 5, 0, 1);

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', '[literal]',
    '[literal]', v_inviter_name,
    '[literal]', jsonb_build_object('[literal]', 5, '[literal]', 0, '[literal]', 1, '[literal]', v_items),
    '[literal]', COALESCE((v_gain ->> '[literal]')::integer, 1) > v_row.level,
    '[literal]', jsonb_build_object('[literal]', '[literal]'::jsonb, '[literal]', '[literal]'::jsonb),
    '[literal]', NULL
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_code text;
  v_try integer := 0;
  v_row public.pet_profiles%ROWTYPE;
  v_invitees jsonb := '[literal]'::jsonb;
  v_vouchers jsonb := '[literal]'::jsonb;
  v_count integer := 0;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_code := v_row.invite_code;
  WHILE v_code IS NULL OR v_code = '[literal]' LOOP
    v_try := v_try + 1;
    v_code := upper(substr(md5(v_uid || clock_timestamp()::text || random()::text), 1, 6));
    BEGIN
      UPDATE public.pet_profiles SET invite_code = v_code, updated_at = now() WHERE uid = v_uid;
    EXCEPTION WHEN unique_violation THEN
      v_code := '[literal]';
    END;
    IF v_try >= 8 THEN EXIT; END IF;
  END LOOP;

  SELECT count(*) INTO v_count FROM public.pet_invites WHERE inviter_uid = v_uid;

  SELECT COALESCE(jsonb_agg(t.x ORDER BY t.at DESC), '[literal]'::jsonb)
    INTO v_invitees
    FROM (
      SELECT jsonb_build_object(
               '[literal]', COALESCE(pr.username, '[literal]'),
               '[literal]', COALESCE(pr.building, '[literal]'),
               '[literal]', i.created_at
             ) AS x,
             i.created_at AS at
        FROM public.pet_invites i
        LEFT JOIN public.profiles pr ON pr.uid = i.invitee_uid
       WHERE i.inviter_uid = v_uid
       ORDER BY i.created_at DESC
       LIMIT 50
    ) t;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           '[literal]', e.voucher_code,
           '[literal]', e.reward_key,
           '[literal]', e.reward_name,
           '[literal]', e.created_at
         ) ORDER BY e.created_at DESC), '[literal]'::jsonb)
    INTO v_vouchers
    FROM public.pet_exchanges e
   WHERE e.uid = v_uid;

  RETURN jsonb_build_object(
    '[literal]', COALESCE(v_code, '[literal]'),
    '[literal]', v_count,
    '[literal]', v_invitees,
    '[literal]', COALESCE(v_row.shard_progress, 0),
    '[literal]', COALESCE(v_row.gacha_tickets, 0),
    '[literal]', to_jsonb(COALESCE(v_row.level_rewards_claimed, ARRAY[]::integer[])),
    '[literal]', v_vouchers
  );
END;

DECLARE
  v_qty integer;
BEGIN
  IF p_uid IS NULL OR p_item IS NULL OR p_item = '[literal]' OR COALESCE(p_delta, 0) = 0 THEN
    RETURN jsonb_build_object('[literal]', COALESCE(p_item, '[literal]'), '[literal]', 0, '[literal]', 0);
  END IF;

  SELECT COALESCE((inventory ->> p_item)::integer, 0)
    INTO v_qty
    FROM public.pet_profiles WHERE uid = p_uid FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('[literal]', p_item, '[literal]', 0, '[literal]', 0);
  END IF;

  v_qty := GREATEST(0, COALESCE(v_qty, 0) + p_delta);

  UPDATE public.pet_profiles
     SET inventory = jsonb_set(COALESCE(inventory, '[literal]'::jsonb), ARRAY[p_item], to_jsonb(v_qty), true),
         updated_at = now()
   WHERE uid = p_uid;

  INSERT INTO public.pet_item_logs (uid, item, delta, balance, reason)
  VALUES (p_uid, p_item, p_delta, v_qty, COALESCE(p_reason, '[literal]'));

  RETURN jsonb_build_object('[literal]', p_item, '[literal]', p_delta, '[literal]', v_qty);
END;

DECLARE
  v_uid text := auth.uid();
  v_name text := btrim(COALESCE(p_pet_name, '[literal]'));
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_name = '[literal]' OR char_length(v_name) > 12 THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.pet_profiles WHERE uid = v_uid) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  UPDATE public.pet_profiles SET pet_name = v_name WHERE uid = v_uid;

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', jsonb_build_object('[literal]', 0, '[literal]', 0, '[literal]', 0),
    '[literal]', jsonb_build_object('[literal]', '[literal]'::jsonb, '[literal]', '[literal]'::jsonb)
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_action text := lower(btrim(COALESCE(p_action, '[literal]')));
  v_day date := (now() AT TIME ZONE '[literal]')::date;
  v_exp integer;
  v_coins integer;
  v_item text;
  v_key text;
  v_used_exp integer;
  v_used_coins integer;
  v_gain jsonb;
  v_new text[];
  v_items jsonb := '[literal]'::jsonb;
  v_before_level integer := 1;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RETURN jsonb_build_object('[literal]', true, '[literal]', '[literal]');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.pet_profiles WHERE uid = v_uid) THEN
    RETURN jsonb_build_object('[literal]', true, '[literal]', '[literal]');
  END IF;

  v_exp := CASE v_action
             WHEN '[literal]' THEN 12
             WHEN '[literal]' THEN 12
             WHEN '[literal]' THEN 6
             WHEN '[literal]' THEN 8
             WHEN '[literal]' THEN 12
             WHEN '[literal]' THEN 10
             WHEN '[literal]' THEN 12
             WHEN '[literal]' THEN 6
             WHEN '[literal]' THEN 8
             ELSE 0
           END;
  v_coins := CASE v_action
              WHEN '[literal]' THEN 8
              WHEN '[literal]' THEN 8
              WHEN '[literal]' THEN 4
              WHEN '[literal]' THEN 5
              WHEN '[literal]' THEN 8
              WHEN '[literal]' THEN 6
              WHEN '[literal]' THEN 8
              WHEN '[literal]' THEN 4
              WHEN '[literal]' THEN 5
              ELSE 0
            END;
  v_item := CASE v_action
             WHEN '[literal]' THEN '[literal]'
             WHEN '[literal]' THEN '[literal]'
             WHEN '[literal]' THEN '[literal]'
             WHEN '[literal]' THEN '[literal]'
             WHEN '[literal]' THEN '[literal]'
             ELSE '[literal]'
           END;
  IF v_exp = 0 THEN
    RETURN jsonb_build_object('[literal]', true, '[literal]', '[literal]');
  END IF;

  v_key := '[literal]' || v_action || '[literal]' || v_day::text;

  BEGIN
    INSERT INTO public.pet_actions (uid, action, exp_delta, coin_delta, dedupe_key, day)
    VALUES (v_uid, '[literal]' || v_action, v_exp, v_coins, v_key, v_day);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('[literal]', true, '[literal]', '[literal]');
  END;

  -- 当日上限：经验 60 / 金币 40，超出部分从本条扣减
  SELECT COALESCE(sum(exp_delta), 0), COALESCE(sum(coin_delta), 0)
    INTO v_used_exp, v_used_coins
    FROM public.pet_actions
   WHERE uid = v_uid AND day = v_day AND dedupe_key LIKE '[literal]';

  IF v_used_exp > 60 OR v_used_coins > 40 THEN
    v_exp := GREATEST(0, v_exp - GREATEST(0, v_used_exp - 60));
    v_coins := GREATEST(0, v_coins - GREATEST(0, v_used_coins - 40));
    UPDATE public.pet_actions
       SET exp_delta = v_exp, coin_delta = v_coins
     WHERE uid = v_uid AND dedupe_key = v_key;
    IF v_exp = 0 AND v_coins = 0 THEN
      RETURN jsonb_build_object('[literal]', true, '[literal]', '[literal]');
    END IF;
  END IF;

  PERFORM public.pet_settle(v_uid);
  SELECT level INTO v_before_level FROM public.pet_profiles WHERE uid = v_uid;
  v_gain := public.pet_gain(v_uid, v_exp, v_coins, 1);
  v_new := public.pet_unlock_many(v_uid, ARRAY['[literal]' || v_action]);

  IF v_item <> '[literal]' THEN
    PERFORM public.pet_item_add(v_uid, v_item, 1, '[literal]' || v_action);
    v_items := jsonb_set(v_items, ARRAY[v_item], to_jsonb(1), true);
  END IF;

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', jsonb_build_object('[literal]', v_exp, '[literal]', v_coins, '[literal]', 1, '[literal]', v_items),
    '[literal]', COALESCE((v_gain ->> '[literal]')::integer, 1) > COALESCE(v_before_level, 1),
    '[literal]', jsonb_build_object(
      '[literal]', to_jsonb(v_new),
      '[literal]', COALESCE(v_gain -> '[literal]', '[literal]'::jsonb)
    )
  );
END;

DECLARE
  v_uid text := auth.uid();
  v_species text := btrim(COALESCE(p_species, '[literal]'));
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  -- 白名单校验：新增形象时同步维护（与前端 data/pet.ts PET_SPECIES 同源）
  IF v_species NOT IN (
    '[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]',
    '[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]', '[literal]'
  ) THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.pet_profiles WHERE uid = v_uid) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  UPDATE public.pet_profiles
     SET species = v_species,
         updated_at = now()
   WHERE uid = v_uid;

  RETURN jsonb_build_object(
    '[literal]', public.pet_snapshot(v_uid),
    '[literal]', jsonb_build_object('[literal]', 0, '[literal]', 0, '[literal]', 0),
    '[literal]', jsonb_build_object('[literal]', '[literal]'::jsonb, '[literal]', '[literal]'::jsonb)
  );
END;

DECLARE
  v_row public.pet_profiles%ROWTYPE;
  v_elapsed integer;
  v_total integer;
  v_minutes integer;
  v_sat integer;
  v_clean integer;
  v_mood integer;
BEGIN
  SELECT * INTO v_row FROM public.pet_profiles WHERE uid = p_uid FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;

  v_elapsed := GREATEST(0, FLOOR(EXTRACT(EPOCH FROM (now() - v_row.last_tick_at)) / 60)::integer);
  v_total := v_row.tick_carry_minutes + v_elapsed;
  v_minutes := v_total;                       -- 每 1 分钟一个刻度，无余量损耗
  IF v_minutes <= 0 THEN RETURN; END IF;

  v_sat   := GREATEST(0, v_row.satiation   - v_minutes / 15);   -- 每 15 分钟 -1
  v_clean := GREATEST(0, v_row.cleanliness - v_minutes / 30);   -- 每 30 分钟 -1
  v_mood  := GREATEST(0, v_row.mood        - v_minutes / 20);   -- 每 20 分钟 -1
  -- 又饿又脏时心情加速下滑
  IF v_sat < 25 OR v_clean < 25 THEN
    v_mood := GREATEST(0, v_mood - v_minutes / 90);
  END IF;

  UPDATE public.pet_profiles
     SET satiation = v_sat,
         cleanliness = v_clean,
         mood = v_mood,
         tick_carry_minutes = 0,
         last_tick_at = now(),
         updated_at = now()
   WHERE uid = p_uid;
END;

