  IF v_phone = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT status INTO v_status FROM public.rider_profiles WHERE uid = v_uid;
  IF v_status = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_status = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
