   WHERE o.id = p_order_id
     AND o.mode = '[literal]'
     AND o.status IN ('[literal]', '[literal]')
     AND o.delivery_status IN ('[literal]', '[literal]', '[literal]')
     AND (public.is_admin_user() OR o.rider_uid = v_uid)
  RETURNING o.id INTO v_hit;

  IF v_hit IS NULL THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  RETURN true;
END;

SELECT EXISTS (
  SELECT 1 FROM public.rider_profiles rp
  WHERE rp.uid = auth.uid() AND rp.status = '[literal]'
);

BEGIN
  -- 管理员放行（治理操作）
  IF public.is_admin_user() THEN
    RETURN NEW;
  END IF;
  -- 本人重新提交：审核结论回到待审（rejected -> pending，配合 rider_apply 的 upsert 路径）
  IF NEW.uid = auth.uid() AND NEW.status = '[literal]' AND OLD.status IN ('[literal]', '[literal]') THEN
    RETURN NEW;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status
     OR NEW.reply IS DISTINCT FROM OLD.reply
     OR NEW.handled_at IS DISTINCT FROM OLD.handled_at THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF btrim(COALESCE(reason, '[literal]')) = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  UPDATE public.rider_profiles
     SET status = '[literal]', reply = reason, handled_at = now(),
         online = false, updated_at = now()
   WHERE uid = p_uid AND status IN ('[literal]', '[literal]', '[literal]');
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  RETURN true;
END;

DECLARE
  v_n integer;
  v_min integer := GREATEST(COALESCE(p_minutes, 30), 5);
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  WITH stale AS (
    UPDATE public.canteen_orders o
       SET rider_uid = '[literal]',
           rider_name = '[literal]',
           rider_phone = '[literal]',
           delivery_status = '[literal]',
           delivery_taken_at = NULL,
           delivery_done_at = NULL,
           delivery_note = '[literal]',
           updated_at = now()
     WHERE o.mode = '[literal]' AND o.status = '[literal]'
       -- 同时覆盖「接单后一直不取餐」与「取餐后一直不送达」两种卡单场景
       AND o.delivery_status IN ('[literal]', '[literal]', '[literal]')
       AND o.delivery_taken_at < now() - make_interval(mins => v_min)
    RETURNING o.id
  )
  SELECT count(*) INTO v_n FROM stale;
  RETURN v_n;
END;

BEGIN
