DECLARE
  v_applicant text;
  v_role text;
  v_payload jsonb;
  v_reason text := btrim(COALESCE(p_reason, '[literal]'));
  v_name text := '[literal]';
  v_emoji text := '[literal]';
  v_building text := '[literal]';
  v_desc text := '[literal]';
  v_phone text := '[literal]';
  v_category text := '[literal]';
  v_tags text[] := '[literal]';
  v_display text := '[literal]';
  v_store_id bigint;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT a.uid, a.role, a.payload INTO v_applicant, v_role, v_payload
    FROM public.role_apps a
   WHERE a.id = p_app_id AND a.status = '[literal]';
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 驳回：填写原因即可，业务侧不落地
  IF NOT p_ok THEN
    IF v_reason = '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    UPDATE public.role_apps
       SET status = '[literal]', reply = v_reason, handled_at = now(), updated_at = now()
     WHERE id = p_app_id AND status = '[literal]';
    IF NOT FOUND THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    RETURN true;
  END IF;

  -- 通过：原子占位申请单（并发下只有一个管理员能抢到）
  UPDATE public.role_apps
     SET status = '[literal]', reply = '[literal]', handled_at = now(), updated_at = now()
   WHERE id = p_app_id AND status = '[literal]';
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_role = '[literal]' THEN
    -- 档口：按既有 canteen_stores 列默认与 CHECK 建档（或复用已存在档口），并回填 ref_id
    v_name := COALESCE(NULLIF(btrim(COALESCE(v_payload ->> '[literal]', '[literal]')), '[literal]'), '[literal]');
    v_emoji := COALESCE(NULLIF(btrim(COALESCE(v_payload ->> '[literal]', '[literal]')), '[literal]'), '[literal]');
    v_building := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_desc := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_tags := COALESCE(
      (SELECT array_agg(t) FROM jsonb_array_elements_text(COALESCE(v_payload -> '[literal]', '[literal]'::jsonb)) AS x(t)),
      '[literal]'
    );
    v_display := v_name;

    SELECT s.id INTO v_store_id
      FROM public.canteen_stores s
     WHERE s.owner_uid = v_applicant
     ORDER BY s.created_at
     LIMIT 1;

    IF v_store_id IS NULL THEN
      INSERT INTO public.canteen_stores (owner_uid, name, emoji, description, tags, building, status)
      VALUES (v_applicant, v_name, v_emoji, v_desc, v_tags, v_building, '[literal]')
      RETURNING id INTO v_store_id;
    ELSE
      UPDATE public.canteen_stores
         SET name = v_name, emoji = v_emoji, description = v_desc, tags = v_tags,
             building = v_building, status = '[literal]', updated_at = now()
       WHERE id = v_store_id;
    END IF;

  ELSIF v_role = '[literal]' THEN
    -- 骑手：开通既有的 rider_profiles 身份（该表同时承载骑手在线开关与配送归属）
    v_name := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_phone := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_building := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_desc := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    IF v_name = '[literal]' OR v_phone = '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    v_display := v_name;

    INSERT INTO public.rider_profiles (uid, real_name, phone, zone, note, status, reply, handled_at, online)
    VALUES (v_applicant, v_name, v_phone, v_building, v_desc, '[literal]', '[literal]', now(), false)
    ON CONFLICT (uid) DO UPDATE
       SET real_name = EXCLUDED.real_name,
           phone = EXCLUDED.phone,
           zone = EXCLUDED.zone,
           note = EXCLUDED.note,
           status = '[literal]',
           reply = '[literal]',
           handled_at = now(),
           updated_at = now();

  ELSE
    -- 小店：仅开通成员身份，商品与流水由工作台自行维护
    v_category := btrim(COALESCE(v_payload ->> '[literal]', '[literal]'));
    v_display := COALESCE(NULLIF(btrim(COALESCE(v_payload ->> '[literal]', '[literal]')), '[literal]'), '[literal]');
  END IF;

  -- 成员开通（幂等：重复审批/停用恢复共用同一路径）
  INSERT INTO public.role_members (uid, role, status, display_name, ref_id, joined_at)
  VALUES (v_applicant, v_role, '[literal]', v_display, v_store_id, now())
  ON CONFLICT (uid, role) DO UPDATE
     SET status = '[literal]',
         display_name = EXCLUDED.display_name,
         ref_id = COALESCE(EXCLUDED.ref_id, public.role_members.ref_id),
         updated_at = now();

  RETURN true;
END;

DECLARE
  v_role text := lower(btrim(COALESCE(p_role, '[literal]')));
  v_store record;
  v_has_store boolean := false;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_role NOT IN ('[literal]', '[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_role IN ('[literal]', '[literal]') THEN
    -- 停用owner整个经营角色的旧接口必须在枚举前取得与建店相同的锁。
    PERFORM pg_advisory_xact_lock(612004, 1);
    FOR v_store IN
      SELECT s.id FROM public.shop_stores s WHERE v_role = '[literal]' AND s.owner_uid = p_uid
      UNION ALL
      SELECT s.id FROM public.canteen_stores s WHERE v_role = '[literal]' AND s.owner_uid = p_uid
      ORDER BY id
    LOOP
      v_has_store := true;
      PERFORM public.admin_operation_revoke(v_role, v_store.id, '[literal]', false);
    END LOOP;
    IF v_has_store THEN RETURN true; END IF;
  END IF;

  UPDATE public.role_members
     SET status = '[literal]', updated_at = now()
   WHERE uid = p_uid AND role = v_role AND status = '[literal]';
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 业务侧同步：骑手立刻下线且不可再推进配送；档口转为歇业（公开视图随之下架）
  IF v_role = '[literal]' THEN
    UPDATE public.rider_profiles
       SET status = '[literal]', online = false, handled_at = now(), updated_at = now()
     WHERE uid = p_uid;
  ELSIF v_role = '[literal]' THEN
    UPDATE public.canteen_stores
       SET status = '[literal]', updated_at = now()
     WHERE owner_uid = p_uid;
  END IF;

  RETURN true;
END;

DECLARE
  has_img boolean := NEW.images IS NOT NULL AND COALESCE(cardinality(NEW.images), 0) > 0;
BEGIN
  IF TG_OP = '[literal]' THEN
    -- 新发布：无图直接放行（none）；带图一律进入待审
    IF NOT has_img THEN
      NEW.img_state := '[literal]';
    ELSIF NEW.img_state IN ('[literal]', '[literal]') THEN
      NEW.img_state := '[literal]';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE：图片有变动则重新送审
  IF has_img AND NEW.images IS DISTINCT FROM OLD.images
     AND NEW.img_state IN ('[literal]', '[literal]') THEN
    NEW.img_state := '[literal]';
  END IF;

  -- 非管理员不得把自己从待审/违规 改回放行
  IF NOT public.is_admin_user() AND NEW.img_state = '[literal]'
     AND OLD.img_state IN ('[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  RETURN NEW;
END;

BEGIN
  -- 状态未变（改内容等）直接放行
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;

  -- 管理员（治理 / 审核回写 / 违规下架）不受普通用户状态流约束
  IF public.is_admin_user() THEN
    IF NEW.status = '[literal]' AND btrim(COALESCE(NEW.reject_reason, '[literal]')) = '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    RETURN NEW;
  END IF;

  -- 普通提交者：撤回待审 / 下架 / 标记已售（仅车源）/ 重新提交待审 / 驳回后修改重提
  IF (OLD.status = '[literal]' AND NEW.status = '[literal]')
     OR (OLD.status = '[literal]' AND NEW.status = '[literal]')
     OR (OLD.status = '[literal]' AND NEW.status = '[literal]' AND TG_TABLE_NAME = '[literal]')
     OR (OLD.status = '[literal]' AND NEW.status = '[literal]')
     OR (OLD.status = '[literal]' AND NEW.status = '[literal]') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION '[literal]';
END;

BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;

  -- 管理员治理放行（违规关闭等）
  IF public.is_admin_user() THEN RETURN NEW; END IF;

  -- 认领（open -> taken）：须本人认领、禁止自接；并发多接由行锁 + WHERE status='[literal]' 兜底
  IF NEW.status = '[literal]' THEN
    IF OLD.status <> '[literal]' THEN RAISE EXCEPTION '[literal]'; END IF;
    IF auth.uid() IS DISTINCT FROM NEW.taker_uid OR NEW.taker_uid IS NULL THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    IF NEW.taker_uid = OLD.publisher_uid THEN RAISE EXCEPTION '[literal]'; END IF;
    NEW.taken_at := now();
    RETURN NEW;
  END IF;

  -- 仅发布者可确认完成（taken -> done）
  IF NEW.status = '[literal]' THEN
    IF OLD.status <> '[literal]' THEN RAISE EXCEPTION '[literal]'; END IF;
    IF auth.uid() IS DISTINCT FROM OLD.publisher_uid THEN RAISE EXCEPTION '[literal]'; END IF;
    RETURN NEW;
  END IF;

  -- 取消：发布者（open/taken 均可取消）；接单者在已接单后可退出
  IF NEW.status = '[literal]' THEN
    IF OLD.status NOT IN ('[literal]', '[literal]') THEN RAISE EXCEPTION '[literal]'; END IF;
    IF auth.uid() = OLD.publisher_uid OR (OLD.status = '[literal]' AND auth.uid() = OLD.taker_uid) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 其余状态迁移一律不允许普通用户直改
  RAISE EXCEPTION '[literal]';
END;

DECLARE v_nm text;
