DECLARE v_nm text;
BEGIN
  SELECT p.username INTO v_nm FROM public.profiles p
   WHERE p.uid = COALESCE(auth.uid(), NEW.publisher_uid) AND btrim(COALESCE(p.username,'[literal]')) <> '[literal]'
   LIMIT 1;
  IF v_nm IS NOT NULL THEN NEW.publisher_name := v_nm; END IF;
  RETURN NEW;
END;

BEGIN
  IF NEW.promo_mode = '[literal]' AND NEW.status = '[literal]' AND coalesce(NEW.group_min_members, 0) > 0 THEN
    UPDATE public.shop_groups g
       SET group_price = NEW.group_price,
           min_members = NEW.group_min_members,
           deadline    = coalesce(NEW.group_deadline, g.deadline)
     WHERE g.goods_id = NEW.id AND g.status = '[literal]';

    IF NOT FOUND THEN
      INSERT INTO public.shop_groups (store_id, goods_id, group_price, min_members, deadline)
      VALUES (NEW.store_id, NEW.id, NEW.group_price, NEW.group_min_members,
              coalesce(NEW.group_deadline, now() + interval '[literal]'))
      ON CONFLICT DO NOTHING;
    END IF;
  ELSE
    -- 改成非拼团 / 下架：只关闭还没有人报名的空场次，避免吞掉已有报名
    UPDATE public.shop_groups g
       SET status = '[literal]'
     WHERE g.goods_id = NEW.id AND g.status = '[literal]' AND g.member_count = 0;
  END IF;
  RETURN NEW;
END;

DECLARE
  v_uid     text := auth.uid();
  v_mode    text := coalesce(nullif(btrim(p_mode), '[literal]'), '[literal]');
  v_g       public.shop_groups%ROWTYPE;
  v_name    text;
  v_count   int;
  v_qty_sum int;
  v_settle  jsonb;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF coalesce(p_qty, 0) <= 0 THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_mode NOT IN ('[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  -- 行锁：并发参团也不会超员
  SELECT * INTO v_g FROM public.shop_groups WHERE id = p_group_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_g.status <> '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_g.deadline <= now() THEN
    -- 注意：这里不能顺手调用 shop_group_settle —— RAISE 会回滚整个事务，
    -- 结算结果会一起被丢掉。到期场次交由 shop_group_sweep（进店时静默触发）处理。
    RAISE EXCEPTION '[literal]';
  END IF;
  IF NOT public.shop_store_open(v_g.store_id) THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.shop_group_members m
     WHERE m.group_id = v_g.id AND m.uid = v_uid AND m.status <> '[literal]'
  ) THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF (SELECT g.stock FROM public.shop_goods g WHERE g.id = v_g.goods_id) < p_qty THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT coalesce(nullif(btrim(p.username), '[literal]'), '[literal]') INTO v_name
    FROM public.profiles p WHERE p.uid = v_uid;
  v_name := coalesce(v_name, '[literal]');

  INSERT INTO public.shop_group_members (
    group_id, uid, buyer_name, qty, mode, building, contact, note
  ) VALUES (
    v_g.id, v_uid, v_name, p_qty, v_mode,
    coalesce(btrim(p_building), '[literal]'), coalesce(btrim(p_contact), '[literal]'), coalesce(btrim(p_note), '[literal]')
  );

  UPDATE public.shop_groups
     SET member_count = member_count + 1,
         member_qty   = member_qty + p_qty
   WHERE id = v_g.id
  RETURNING member_count, member_qty INTO v_count, v_qty_sum;

  PERFORM public.notify_push(
    (SELECT s.owner_uid FROM public.shop_stores s WHERE s.id = v_g.store_id),
    '[literal]', '[literal]',
    format('[literal]', v_name, p_qty, v_count, v_g.min_members),
    '[literal]', v_g.id
  );

  IF v_count >= v_g.min_members THEN
    v_settle := public.shop_group_settle(v_g.id);
  END IF;

  RETURN jsonb_build_object(
    '[literal]', v_g.id,
    '[literal]', v_count,
    '[literal]', v_qty_sum,
    '[literal]', v_g.min_members,
    '[literal]', coalesce(v_settle->>'[literal]', CASE WHEN v_count >= v_g.min_members THEN '[literal]' ELSE '[literal]' END)
  );
END;

BEGIN
  IF auth.uid() IS NULL OR public.current_is_anon() THEN RETURN false; END IF;
  RETURN EXISTS (SELECT 1 FROM public.shop_group_members m
    WHERE m.group_id=p_group_id AND m.uid=auth.uid());
END;

DECLARE
  v_g          public.shop_groups%ROWTYPE;
  v_goods      public.shop_goods%ROWTYPE;
  v_store_name text;
  v_owner      text;
  v_m          record;
  v_order_id   bigint;
  v_orders     int := 0;
  v_skipped    int := 0;
  v_code       text;
  v_snapshot   jsonb;
BEGIN
  SELECT * INTO v_g FROM public.shop_groups WHERE id = p_group_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_g.status <> '[literal]' THEN
    RETURN jsonb_build_object('[literal]', p_group_id, '[literal]', v_g.status, '[literal]', 0);
  END IF;

  -- 够人就成团（即使已过截止时间，也按成团处理，不让已凑齐的同学白等）
  IF v_g.member_count > 0 AND v_g.member_count >= v_g.min_members THEN
    SELECT * INTO v_goods FROM public.shop_goods WHERE id = v_g.goods_id;
    SELECT s.name, s.owner_uid INTO v_store_name, v_owner
      FROM public.shop_stores s WHERE s.id = v_g.store_id;

    FOR v_m IN
      SELECT * FROM public.shop_group_members
       WHERE group_id = p_group_id AND status = '[literal]'
       ORDER BY id
    LOOP
      IF coalesce(v_goods.stock, 0) < v_m.qty THEN
        -- 库存被单买吃掉时不再超卖：该成员作废并单独通知
        UPDATE public.shop_group_members SET status = '[literal]' WHERE id = v_m.id;
        PERFORM public.notify_push(
          v_m.uid, '[literal]', '[literal]',
          format('[literal]', coalesce(v_goods.name, '[literal]')),
          '[literal]', p_group_id
        );
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      v_code := lpad(((1000 + floor(random() * 9000))::int)::text, 4, '[literal]');
      v_snapshot := jsonb_build_array(jsonb_build_object(
        '[literal]', v_goods.id,
        '[literal]',    v_goods.name,
        '[literal]',   coalesce(v_goods.images->>0, '[literal]'),
        '[literal]',    v_goods.unit,
        '[literal]',   v_g.group_price,
        '[literal]',     v_m.qty
      ));

      INSERT INTO public.shop_orders (
        store_id, buyer_uid, buyer_name, mode, building, contact, note,
        items, total, status, pickup_code, group_id
      ) VALUES (
        v_g.store_id, v_m.uid, v_m.buyer_name, v_m.mode, v_m.building, v_m.contact,
        CASE WHEN v_m.note = '[literal]' THEN '[literal]' ELSE v_m.note END,
        v_snapshot, v_g.group_price * v_m.qty, '[literal]', v_code, v_g.id
      )
      RETURNING id INTO v_order_id;

      UPDATE public.shop_group_members
         SET status = '[literal]', order_id = v_order_id
       WHERE id = v_m.id;

      v_goods.stock := v_goods.stock - v_m.qty;
      v_orders := v_orders + 1;
    END LOOP;

    UPDATE public.shop_goods
       SET stock      = greatest(v_goods.stock, 0),
           sold_out   = (v_goods.stock <= 0),
           updated_at = now()
     WHERE id = v_g.goods_id;

    UPDATE public.shop_groups
       SET status = '[literal]', formed_at = coalesce(formed_at, now()), settled_at = now()
     WHERE id = p_group_id;

    IF coalesce(v_owner, '[literal]') <> '[literal]' THEN
      PERFORM public.notify_push(
        v_owner, '[literal]', '[literal]',
        format('[literal]',
               coalesce(v_goods.name, '[literal]'), v_g.member_count, v_orders),
        '[literal]', p_group_id
      );
    END IF;

    FOR v_m IN
      SELECT * FROM public.shop_group_members
       WHERE group_id = p_group_id AND status = '[literal]'
    LOOP
      PERFORM public.notify_push(
        v_m.uid, '[literal]', '[literal]',
        format('[literal]',
               coalesce(v_goods.name, '[literal]'), v_m.order_id),
        '[literal]', v_m.order_id
      );
    END LOOP;

    RETURN jsonb_build_object(
      '[literal]', p_group_id, '[literal]', '[literal]',
      '[literal]', v_orders, '[literal]', v_skipped
    );
  END IF;

  -- 人数不够且已过截止时间 → 作废（零支付，无需退款）
  IF v_g.deadline <= now() THEN
    UPDATE public.shop_group_members SET status = '[literal]'
     WHERE group_id = p_group_id AND status = '[literal]';

    FOR v_m IN
      SELECT * FROM public.shop_group_members
       WHERE group_id = p_group_id AND status = '[literal]'
    LOOP
      PERFORM public.notify_push(
        v_m.uid, '[literal]', '[literal]',
        format('[literal]',
               coalesce((SELECT g.name FROM public.shop_goods g WHERE g.id = v_g.goods_id), '[literal]'),
               v_g.member_count, v_g.min_members),
        '[literal]', p_group_id
      );
    END LOOP;

    UPDATE public.shop_groups
       SET status = '[literal]', settled_at = now()
     WHERE id = p_group_id;

    RETURN jsonb_build_object('[literal]', p_group_id, '[literal]', '[literal]', '[literal]', 0);
  END IF;

  RETURN jsonb_build_object('[literal]', p_group_id, '[literal]', '[literal]', '[literal]', 0);
END;

BEGIN
  IF auth.uid() IS NULL OR public.current_is_anon() THEN RETURN false; END IF;
  RETURN EXISTS (SELECT 1 FROM public.shop_groups g
    WHERE g.id=p_group_id AND public.shop_is_store_owner(g.store_id));
END;

DECLARE
  v_uid   text := auth.uid();
  v_row   record;
  v_count int := 0;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RETURN 0;
  END IF;

  FOR v_row IN
    SELECT id FROM public.shop_groups
     WHERE status = '[literal]' AND deadline <= now()
     ORDER BY deadline
     LIMIT greatest(coalesce(p_limit, 20), 1)
  LOOP
    PERFORM public.shop_group_settle(v_row.id);
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;

DECLARE
  v_owner      text;
  v_store_name text;
  v_label      text;
BEGIN
  SELECT s.owner_uid, s.name INTO v_owner, v_store_name
    FROM public.shop_stores s
   WHERE s.id = NEW.store_id;

  IF TG_OP = '[literal]' THEN
    IF coalesce(v_owner, '[literal]') <> '[literal]' THEN
      PERFORM public.notify_push(
        v_owner, '[literal]', '[literal]',
        format('[literal]',
               coalesce(nullif(btrim(NEW.buyer_name), '[literal]'), '[literal]'),
               to_char(NEW.total::numeric, '[literal]'),
               CASE WHEN NEW.group_id IS NULL THEN '[literal]' ELSE '[literal]' END),
        '[literal]', NEW.id
      );
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    v_label := CASE NEW.status
                 WHEN '[literal]'  THEN '[literal]'
                 WHEN '[literal]'     THEN '[literal]'
                 WHEN '[literal]'      THEN '[literal]'
                 WHEN '[literal]'  THEN '[literal]'
                 WHEN '[literal]' THEN '[literal]'
                 ELSE '[literal]'
               END;

    IF coalesce(NEW.buyer_uid, '[literal]') <> '[literal]' THEN
      PERFORM public.notify_push(
        NEW.buyer_uid, '[literal]', '[literal]',
        format('[literal]', NEW.id, v_label,
               CASE WHEN NEW.status = '[literal]' AND coalesce(btrim(NEW.reject_reason), '[literal]') <> '[literal]'
                    THEN '[literal]' || btrim(NEW.reject_reason)
                    WHEN NEW.status = '[literal]' THEN '[literal]' || NEW.pickup_code
                    ELSE '[literal]' END),
        '[literal]', NEW.id
      );
    END IF;
  END IF;

  RETURN NEW;
END;

DECLARE
  v_uid       text := auth.uid();
  v_mode      text := coalesce(nullif(btrim(p_mode), '[literal]'), '[literal]');
  v_name      text;
  v_lines     int := 0;
  v_total     int := 0;
  v_snapshot  jsonb := '[literal]'::jsonb;
  v_code      text;
  v_order_id  bigint;
  v_item      record;
  v_goods     public.shop_goods%ROWTYPE;
  v_unit      int;
  v_line      int;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF v_mode NOT IN ('[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> '[literal]' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF NOT public.shop_store_open(p_store_id) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT coalesce(nullif(btrim(p.username), '[literal]'), '[literal]') INTO v_name
    FROM public.profiles p WHERE p.uid = v_uid;
  v_name := coalesce(v_name, '[literal]');

  -- 解析并校验购物车（同一商品多次加购合并为一条，阶梯价按合并后的总份数命中）
  FOR v_item IN
    SELECT (e->>'[literal]')::bigint    AS goods_id,
           sum((e->>'[literal]')::int)::int AS qty
      FROM jsonb_array_elements(p_items) AS e
     WHERE jsonb_typeof(e->'[literal]') = '[literal]'
       AND jsonb_typeof(e->'[literal]') = '[literal]'
     GROUP BY 1
     ORDER BY 1
  LOOP
    v_lines := v_lines + 1;

    IF v_item.qty IS NULL OR v_item.qty <= 0 THEN
      RAISE EXCEPTION '[literal]';
    END IF;

    SELECT * INTO v_goods
      FROM public.shop_goods g
     WHERE g.id = v_item.goods_id
       AND g.store_id = p_store_id
       AND g.status = '[literal]'
       AND NOT g.sold_out;
    IF NOT FOUND THEN
      RAISE EXCEPTION '[literal]';
    END IF;

    IF v_goods.promo_mode = '[literal]' THEN
      RAISE EXCEPTION '[literal]', v_goods.name;
    END IF;

    IF v_goods.stock < v_item.qty THEN
      RAISE EXCEPTION '[literal]', v_goods.name, v_goods.stock;
    END IF;

    v_unit := CASE
                WHEN v_goods.promo_mode = '[literal]'
                  THEN public.shop_tier_price(v_goods.price, v_goods.tier_prices, v_item.qty)
                ELSE v_goods.price
              END;
    v_line := v_unit * v_item.qty;

    v_total := v_total + v_line;
    v_snapshot := v_snapshot || jsonb_build_array(jsonb_build_object(
      '[literal]', v_goods.id,
      '[literal]',    v_goods.name,
      '[literal]',   coalesce(v_goods.images->>0, '[literal]'),
      '[literal]',    v_goods.unit,
      '[literal]',   v_unit,
      '[literal]',     v_item.qty
    ));

    -- 原子扣减：并发生成 sold_out 与库存下限都在同一条 UPDATE 内完成
    UPDATE public.shop_goods g
       SET stock      = g.stock - v_item.qty,
           sold_out   = (g.stock - v_item.qty <= 0),
           updated_at = now()
     WHERE g.id = v_goods.id;
  END LOOP;

  IF v_lines = 0 OR v_lines <> (
       SELECT count(DISTINCT (e->>'[literal]'))
         FROM jsonb_array_elements(p_items) AS e
     ) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  v_code := lpad(((1000 + floor(random() * 9000))::int)::text, 4, '[literal]');

  INSERT INTO public.shop_orders (
    store_id, buyer_uid, buyer_name, mode, building, contact, note, items, total, status, pickup_code
  ) VALUES (
    p_store_id, v_uid, v_name, v_mode,
    coalesce(btrim(p_building), '[literal]'), coalesce(btrim(p_contact), '[literal]'), coalesce(btrim(p_note), '[literal]'),
    v_snapshot, v_total, '[literal]', v_code
  )
  RETURNING id INTO v_order_id;

  RETURN jsonb_build_object(
    '[literal]', v_order_id,
    '[literal]', v_code,
    '[literal]', v_total,
    '[literal]', v_lines
  );
END;

DECLARE
  v_uid      text := auth.uid();
  v_order    public.shop_orders%ROWTYPE;
  v_owner    text;
  v_is_owner boolean := false;
  v_is_admin boolean := false;
  v_next     text := coalesce(btrim(p_status), '[literal]');
  v_reason   text := coalesce(btrim(p_reject_reason), '[literal]');
  v_restored int := 0;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_order FROM public.shop_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT s.owner_uid INTO v_owner FROM public.shop_stores s WHERE s.id = v_order.store_id;
  v_is_owner := (coalesce(v_owner, '[literal]') <> '[literal]' AND v_owner = v_uid);
  v_is_admin := public.is_admin_user();

  IF NOT (v_is_owner OR v_is_admin OR v_order.buyer_uid = v_uid) THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_next NOT IN ('[literal]', '[literal]', '[literal]', '[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_order.status IN ('[literal]', '[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  IF v_next = '[literal]' THEN
    -- 买家只能在店主接单前取消；接单后请直接联系店主
    IF NOT (v_is_owner OR v_is_admin) THEN
      IF NOT (v_order.buyer_uid = v_uid AND v_order.status = '[literal]') THEN
        RAISE EXCEPTION '[literal]';
      END IF;
    END IF;
  ELSIF v_next = '[literal]' THEN
    IF NOT (v_is_owner OR v_is_admin) THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    IF v_reason = '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;
  ELSE
    IF NOT (v_is_owner OR v_is_admin) THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    IF v_next = '[literal]' AND v_order.status <> '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    IF v_next = '[literal]' AND v_order.status <> '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    IF v_next = '[literal]' AND v_order.status <> '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;
  END IF;

  UPDATE public.shop_orders
     SET status        = v_next,
         reject_reason = CASE WHEN v_next = '[literal]' THEN v_reason ELSE reject_reason END,
         updated_at    = now()
   WHERE id = p_order_id;

  -- 拒单 / 取消 → 回补库存，避免占用
  IF v_next IN ('[literal]', '[literal]') THEN
    -- 已校验订单身份、状态并锁定订单后签发一次性库存回补许可。
    -- 无客户端表权限，许可绑定事务/原订单/商品/真实actor，不能直接改库存冒充退款。
    INSERT INTO public.operation_stock_refund_authorization(txid, order_id, goods_id, actor_uid, qty)
      SELECT txid_current(), v_order.id, g.id, auth.uid(), sum((line->>'[literal]')::numeric)
      FROM jsonb_array_elements(v_order.items) AS line
      JOIN public.shop_goods g ON g.id = (line->>'[literal]')::bigint
      JOIN public.shop_stores s ON s.id = g.store_id
      WHERE s.operation_revoked AND g.store_id = v_order.store_id
        AND jsonb_typeof(line->'[literal]') = '[literal]' AND (line->>'[literal]')::numeric > 0
      GROUP BY g.id;
    UPDATE public.shop_goods g
       SET stock      = g.stock + returned.qty,
           sold_out   = false,
           updated_at = now()
      FROM (
        SELECT (line->>'[literal]')::bigint AS goods_id, sum((line->>'[literal]')::numeric) AS qty
        FROM jsonb_array_elements(v_order.items) AS line
        WHERE jsonb_typeof(line->'[literal]') = '[literal]' AND (line->>'[literal]')::numeric > 0
        GROUP BY (line->>'[literal]')::bigint
      ) returned
     WHERE g.id = returned.goods_id AND g.store_id = v_order.store_id;
    GET DIAGNOSTICS v_restored = ROW_COUNT;
    DELETE FROM public.operation_stock_refund_authorization
      WHERE txid = txid_current() AND order_id = v_order.id;
  END IF;

  RETURN jsonb_build_object('[literal]', p_order_id, '[literal]', v_next, '[literal]', v_restored);
END;

DECLARE
  v_store public.canteen_stores%ROWTYPE;
  v_closed boolean := coalesce(p_closed, false);
  v_note text := coalesce(btrim(p_note), '[literal]');
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_store FROM public.canteen_stores WHERE id = p_store_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]', p_store_id;
  END IF;

  UPDATE public.canteen_stores
     SET force_closed = v_closed,
         force_close_note = CASE WHEN v_closed THEN v_note ELSE '[literal]' END,
         force_closed_at = CASE WHEN v_closed THEN now() ELSE NULL END
   WHERE id = p_store_id;

  PERFORM public.notify_push(
    v_store.owner_uid, '[literal]',
    CASE WHEN v_closed THEN '[literal]' ELSE '[literal]' END,
    CASE WHEN v_closed
         THEN format('[literal]', v_store.name,
                     CASE WHEN v_note = '[literal]' THEN '[literal]' ELSE '[literal]' || v_note END)
         ELSE format('[literal]', v_store.name) END,
    '[literal]', p_store_id
  );

  RETURN jsonb_build_object('[literal]', p_store_id, '[literal]', v_closed);
END;

DECLARE v_pub text;
BEGIN
  IF public.current_is_anon() THEN RAISE EXCEPTION '[literal]'; END IF;
  SELECT publisher_uid INTO v_pub FROM public.tutor_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION '[literal]'; END IF;
  IF v_pub = auth.uid() THEN RAISE EXCEPTION '[literal]'; END IF;
  UPDATE public.tutor_orders
     SET status = '[literal]', taker_uid = auth.uid(), taken_at = now(), updated_at = now()
   WHERE id = p_order_id AND status = '[literal]';
  IF NOT FOUND THEN RAISE EXCEPTION '[literal]'; END IF;
  RETURN true;
END;

DECLARE
  v_uid text := auth.uid();
  v_bal bigint;
  v_id  bigint;
BEGIN
  IF v_uid IS NULL OR public.current_is_anon() THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF p_account IS NULL OR p_account NOT IN ('[literal]', '[literal]') THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF p_amount_cent IS NULL OR p_amount_cent <= 0 THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF btrim(coalesce(p_real_name, '[literal]')) = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;
  IF btrim(coalesce(p_alipay, '[literal]')) = '[literal]' THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  UPDATE public.wallets
     SET balance_cent = balance_cent - p_amount_cent,
         frozen_cent = frozen_cent + p_amount_cent,
         updated_at = now()
   WHERE uid = v_uid AND account = p_account AND balance_cent >= p_amount_cent
  RETURNING balance_cent INTO v_bal;

  IF NOT FOUND THEN
    SELECT w.balance_cent INTO v_bal
      FROM public.wallets w
     WHERE w.uid = v_uid AND w.account = p_account;
    IF v_bal IS NULL THEN
      RAISE EXCEPTION '[literal]';
    END IF;
    RAISE EXCEPTION '[literal]', to_char(v_bal / 100.0, '[literal]');
  END IF;

  INSERT INTO public.withdraw_apps (uid, account, amount_cent, real_name, alipay)
  VALUES (v_uid, p_account, p_amount_cent, btrim(p_real_name), btrim(p_alipay))
  RETURNING id INTO v_id;

  INSERT INTO public.wallet_ledger (uid, account, kind, amount_cent, balance_after, memo)
  VALUES (v_uid, p_account, '[literal]', -p_amount_cent, v_bal, '[literal]');

  PERFORM public.notify_push(
    v_uid, '[literal]', '[literal]',
    format('[literal]', to_char(p_amount_cent / 100.0, '[literal]')),
    '[literal]', v_id
  );

  RETURN jsonb_build_object('[literal]', v_id, '[literal]', p_amount_cent, '[literal]', v_bal);
END;

DECLARE
  v_app public.withdraw_apps%ROWTYPE;
  v_bal bigint;
  v_reason text;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION '[literal]';
  END IF;

  SELECT * INTO v_app FROM public.withdraw_apps WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[literal]', p_id;
  END IF;
  IF v_app.status <> '[literal]' THEN
    RAISE EXCEPTION '[literal]', v_app.status;
  END IF;

  v_reason := coalesce(btrim(p_reason), '[literal]');

  IF p_ok THEN
    UPDATE public.wallets
       SET frozen_cent = greatest(frozen_cent - v_app.amount_cent, 0),
           updated_at = now()
     WHERE uid = v_app.uid AND account = v_app.account;

    UPDATE public.withdraw_apps
       SET status = '[literal]', reply = v_reason, handled_by = auth.uid(), handled_at = now()
     WHERE id = p_id;

    PERFORM public.notify_push(
      v_app.uid, '[literal]', '[literal]',
      format('[literal]', to_char(v_app.amount_cent / 100.0, '[literal]')),
      '[literal]', p_id
    );
  ELSE
    IF v_reason = '[literal]' THEN
      RAISE EXCEPTION '[literal]';
    END IF;

    UPDATE public.wallets
       SET balance_cent = balance_cent + v_app.amount_cent,
           frozen_cent = greatest(frozen_cent - v_app.amount_cent, 0),
           updated_at = now()
     WHERE uid = v_app.uid AND account = v_app.account
    RETURNING balance_cent INTO v_bal;

    INSERT INTO public.wallet_ledger (uid, account, kind, amount_cent, balance_after, memo)
    VALUES (v_app.uid, v_app.account, '[literal]', v_app.amount_cent, coalesce(v_bal, 0),
            format('[literal]', v_reason));

    UPDATE public.withdraw_apps
       SET status = '[literal]', reply = v_reason, handled_by = auth.uid(), handled_at = now()
     WHERE id = p_id;

    PERFORM public.notify_push(
      v_app.uid, '[literal]', '[literal]',
      format('[literal]', to_char(v_app.amount_cent / 100.0, '[literal]'), v_reason),
      '[literal]', p_id
    );
  END IF;

  RETURN jsonb_build_object(
    '[literal]', p_id,
    '[literal]', CASE WHEN p_ok THEN '[literal]' ELSE '[literal]' END
  );
END;
